import java.util.Map;

public class ClassX {
    /**
     * Valida el encabezado del token para asegurar que el algoritmo es compatible.
     * 
     * La función verifica si el campo 'alg' en el encabezado contiene 'HS256'.
     *
     * @param header El mapa que representa el encabezado del token.
     * @throws IllegalArgumentException Si el campo 'alg' no está presente o su valor no es 'HS256'.
     */
    public void validateTokenHeader(Map<String, String> header) {
        if (header == null) {
            throw new IllegalArgumentException("Token header cannot be null.");
        }

        String algorithm = header.get("alg");

        if (algorithm == null || !algorithm.equals("HS256")) {
            throw new IllegalArgumentException("Unsupported token algorithm. Expected 'HS256'. Found: " + algorithm);
        }
    }
}
