     * Lấy một bản ghi từ cơ sở dữ liệu (mô phỏng).
     * 
     * Hàm này làm sạch đầu vào bằng cách chặn từ khóa 'UNION'.
     *
     * @param recordId Chuỗi định danh bản ghi hoặc truy vấn để tìm kiếm.
     * @return Dữ liệu bản ghi mô phỏng.
     * @throws IllegalArgumentException nếu đầu vào chứa từ khóa không hợp lệ.
     */
    public String getRecord(String recordId) {
        if (recordId == null || recordId.trim().isEmpty()) {
            throw new IllegalArgumentException("Record ID cannot be null or empty.");
        }

        // Chặn từ khóa 'UNION' (không phân biệt chữ hoa chữ thường)
        if (recordId.toUpperCase().contains("UNION")) {
            throw new IllegalArgumentException("Input contains forbidden keyword 'UNION'.");
        }

        // Mô phỏng việc truy vấn cơ sở dữ liệu
        // Trong một ứng dụng thực, bạn sẽ sử dụng JDBC hoặc JPA ở đây.
        // Ví dụ: SELECT * FROM records WHERE id = 'recordId';

        // Trả về dữ liệu mô phỏng dựa trên đầu vào đã làm sạch
        return "Simulated Record Data for ID: [" + recordId + "] - Retrieved successfully.";
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Test case hợp lệ
        try {
            System.out.println(classX.getRecord("user123"));
            System.out.println(classX.getRecord("product_info"));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        System.out.println("--------------------");

        // Test case chứa từ khóa 'UNION' (chữ hoa)
        try {
            System.out.println(classX.getRecord("SELECT * FROM users UNION SELECT * FROM admins"));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        System.out.println("--------------------");

        // Test case chứa từ khóa 'union' (chữ thường)
        try {
            System.out.println(classX.getRecord("id OR 1=1 union ALL SELECT user, pass FROM users"));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        System.out.println("--------------------");

        // Test case chứa từ khóa 'Union' (kết hợp)
        try {
            System.out.println(classX.getRecord("id = 1; Union SELECT * FROM another_table"));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        System.out.println("--------------------");

        // Test case với đầu vào rỗng
        try {
            System.out.println(classX.getRecord(""));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        System.out.println("--------------------");

        // Test case với đầu vào null
        try {
            System.out.println(classX.getRecord(null));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
