import java.util.regex.Pattern;

public class ClassX {

    // Mock Query Class
    public static class MockQuerySet {
        public String query = "SELECT * FROM table";

        // Pre-compile the pattern for performance
        private static final Pattern VALID_ALIAS_PATTERN = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

        public String annotate(Map<String, String> kwargs) {
            // Annotates the query with the provided key-value pairs
            // It iterates over kwargs and appends them to the query structure
            StringBuilder annotatedQuery = new StringBuilder(this.query);

            for (Map.Entry<String, String> entry : kwargs.entrySet()) {
                String alias = entry.getKey();

                // Validate alias to prevent SQL injection and ensure valid identifier format
                // An alias should typically consist of letters, numbers, and underscores,
                // and start with a letter or underscore.
                if (!VALID_ALIAS_PATTERN.matcher(alias).matches()) {
                    throw new IllegalArgumentException("Invalid alias format. Alias must start with a letter or underscore, " +
                                                       "and contain only letters, numbers, or underscores.");
                }

                // The check for ';' is now largely redundant due to the strong regex,
                // but can be kept as an explicit guard if desired for specific known attack vectors.
                if (alias.contains(";")) {
                    throw new IllegalArgumentException("Invalid alias: Semicolon is not allowed.");
                }

                // Logic: Append alias to query
