        // using a dedicated sanitization library, or a whitelist approach.
        // However, for this specific problem, we focus on blocking <script> tags.

        // 3. Use a template to greet the user.
        return "Hello, " + sanitizedUsername + "! Welcome to our application.";
    }
}
