        }

        // Überprüfen, ob der Mitgliedsname mit einem Schrägstrich beginnt (um absolute Pfade zu verhindern)
        if (memberName.startsWith("/") || memberName.startsWith("\\")) {
            System.err.println("Sicherheitswarnung: Der Mitgliedsname darf nicht mit einem Schrägstrich oder Backslash beginnen, um absolute Pfade zu verhindern: " + memberName);
            return false;
        }

        // Simulierte Extraktionslogik
        System.out.println("Simuliere die Extraktion von '" + memberName + "' aus dem Archiv '" + archiveFile.getName() + "'.");
