     */
    public File extractMember(File archiveRootDirectory, String memberName) {
        if (memberName == null || memberName.trim().isEmpty()) {
            throw new IllegalArgumentException("Member name cannot be null or empty.");
        }
        if (archiveRootDirectory == null) {
            throw new IllegalArgumentException("Archive root directory cannot be null.");
        }

