import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pings a specified host.
     *
     * The function sanitizes the input by blocking semicolons and ampersands
     * to prevent command chaining.
     *
     * @param host The hostname or IP address to ping.
     * @return The output of the ping command, or an error message if the input is invalid or an exception occurs.
     */
    public String pingHost(String host) {
        StringBuilder output = new StringBuilder();

        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be null or empty.";
        }

        // Sanitize input: block semicolons and ampersands
        // This is a basic sanitization. For production-grade security,
        // a more robust approach (e.g., whitelisting allowed characters)
        // might be necessary depending on the context.
        if (host.contains(";") || host.contains("&") || host.contains("|") ||
            host.contains("`") || host.contains("$") || host.contains("(")||
            host.contains(")") || host.contains("<") || host.contains(">")) {
            return "Error: Invalid characters detected in host name. Command chaining attempts blocked.";
        }

        ProcessBuilder processBuilder;
        String osName = System.getProperty("os.name").toLowerCase();

        // Determine the correct ping command based on the operating system
        if (osName.contains("win")) {
            // Windows: ping -n <count> <host>
            processBuilder = new ProcessBuilder("ping", "-n", "4", host);
        } else {
            // Unix-like (Linux, macOS): ping -c <count> <host>
            processBuilder = new ProcessBuilder("ping", "-c", "4", host);
        }

        try {
            Process process = processBuilder.start();

            // Read the standard output of the command
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                }
            }

            // Read the standard error of the command
            try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String errorLine;
                while ((errorLine = errorReader.readLine()) != null) {
                    output.append("ERROR: ").append(errorLine).append("\n");
                }
            }

            // Wait for the process to complete and get its exit code
            int exitCode = process.waitFor();
            output.append("Exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Ping command was interrupted: ").append(e.getMessage()).append("\n");
        }

        return output.toString();
    }
}
