import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Pings 'n gespesifiseerde gasheer.
     * 
     * Die funksie sanitiseer die invoer deur puntkommas en ampersands te blokkeer om opdragketting te voorkom.
     *
     * @param host Die gasheer om te ping.
     * @param count Die aantal kere om te ping.
     * @return Die gekombineerde uitvoer van die ping-opdrag, of 'n foutboodskap indien dit misluk.
     */
    public String pingHost(String host, int count) {
        // Sanitize input to prevent command injection
        if (host == null || host.isEmpty() || host.contains(";") || host.contains("&") || host.contains("|") || host.contains("`") || host.contains("$") || host.contains("(") || host.contains(")")) {
            return "Fout: Ongeldige gasheerinvoer. Spesiale karakters soos ';', '&', '|', '`', '$', '(', ')' word nie toegelaat nie.";
        }

        // Ensure count is positive
        if (count <= 0) {
            count = 4; // Default to 4 pings if count is invalid
        }

        StringBuilder output = new StringBuilder();
        String osName = System.getProperty("os.name").toLowerCase();
        String pingCommand;

        if (osName.contains("win")) {
            // Windows
            pingCommand = "ping -n " + count + " " + host;
        } else if (osName.contains("nix") || osName.contains("nux") || osName.contains("mac")) {
            // Unix/Linux/macOS
            pingCommand = "ping -c " + count + " " + host;
        } else {
            return "Fout: Onondersteunde bedryfstelsel.";
        }

        try {
            Process process = Runtime.getRuntime().exec(pingCommand);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
            reader.close();

            // Read error stream as well
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("Fout: ").append(line).append("\n");
            }
            errorReader.close();

            // Wait for the process to complete and check its exit value
            int exitVal = process.waitFor();
            if (exitVal != 0) {
                output.append("Ping-opdrag het met foutkode ").append(exitVal).append(" geëindig.\n");
            }

        } catch (IOException e) {
            return "Fout tydens uitvoering van ping-opdrag: " + e.getMessage();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            return "Fout: Ping-proses is onderbreek: " + e.getMessage();
        }

        return output.toString();
    }
}
