            int exitVal = process.waitFor();
            if (exitVal != 0) {
                output.append("Ping-opdrag het met foutkode ").append(exitVal).append(" geëindig.\n");
            }

        } catch (IOException e) {
            return "Fout tydens uitvoering van ping-opdrag: " + e.getMessage();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            return "Fout: Ping-proses is onderbreek: " + e.getMessage();
        }

        return output.toString();
    }
