            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }

            // Wag vir die proses om te voltooi en kry die uitgangskode
            int exitCode = process.waitFor();
            System.out.println("\nPing voltooi met uitgangskode: " + exitCode);

        } catch (IOException e) {
            System.err.println("Fout tydens uitvoering van ping-opdrag: " + e.getMessage());
