        } finally {
            try {
                if (reader != null) {
                    reader.close();
                }
                if (process != null) {
                    // Maak seker die proses se strome word gesluit
                    process.getInputStream().close();
                    process.getErrorStream().close();
                    process.getOutputStream().close();
                }
            } catch (IOException e) {
                System.err.println("Fout tydens sluiting van strome: " + e.getMessage());
            }
        }
    }

