    public String pingHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be empty.";
        }

        // Sanitize the input by removing semicolons and ampersands
        // This prevents command chaining like "host; malicious_command" or "host & malicious_command"
        String sanitizedHost = host.replaceAll("[;&]", "");

        // Determine the ping command based on the operating system
        String osName = System.getProperty("os.name").toLowerCase();
        String command;
        if (osName.contains("win")) {
            // For Windows: ping -n <count> <host>
            command = "ping -n 4 " + sanitizedHost;
        } else {
            // For Unix-like systems (Linux, macOS): ping -c <count> <host>
            command = "ping -c 4 " + sanitizedHost;
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;
        BufferedReader errorReader = null;

        try {
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            process = processBuilder.start();

            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Also read error stream in case ping command itself fails or for error messages
            errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("Error: ").append(line).append("\n");
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Ping command exited with code: ").append(exitCode).append("\n");
            }

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Ping command interrupted: ").append(e.getMessage()).append("\n");
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Ignore, or log if necessary
                }
            }
            if (errorReader != null) {
                try {
                    errorReader.close();
                } catch (IOException e) {
                    // Ignore, or log if necessary
                }
            }
            if (process != null) {
                process.destroy(); // Ensure the process is terminated
            }
        }
        return output.toString();
    }

