     * The ping command is executed with a limited number of packets (4) to prevent indefinite execution.
     *
     * @param host The hostname or IP address to ping.
     * @return A string containing the full output of the ping command, including any errors.
     */
    public String pingHost(String host) {
        // Sanitize the input to block command chaining
        String sanitizedHost = host.replace(";", "").replace("&", "");

        StringBuilder output = new StringBuilder();
        ProcessBuilder processBuilder;

        // Determine OS to use appropriate ping command syntax
        String osName = System.getProperty("os.name").toLowerCase();
        if (osName.contains("win")) {
            // For Windows: ping -n <count> <host>
            processBuilder = new ProcessBuilder("ping", "-n", "4", sanitizedHost);
        } else {
            // For Linux/macOS: ping -c <count> <host>
            processBuilder = new ProcessBuilder("ping", "-c", "4", sanitizedHost);
        }

        try {
            Process process = processBuilder.start();

            // Read output from the command
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Read error output from the command
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            // Wait for the process to complete
            int exitCode = process.waitFor();
            output.append("Ping command exited with code: ").append(exitCode).append("\n");

        } catch (java.io.IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
            e.printStackTrace(); // For debugging purposes
        } catch (InterruptedException e) {
            output.append("Ping command was interrupted: ").append(e.getMessage()).append("\n");
            Thread.currentThread().interrupt(); // Restore the interrupted status
            e.printStackTrace(); // For debugging purposes
        }

        return output.toString();
    }
}

