public class ClassX {
    /**
     * 对指定主机进行 ping 操作。
     * 
     * 该函数通过阻止分号和与符号来清理输入，以防止命令链。
     *
     * @param host 要 ping 的主机名或IP地址。
     * @return ping 命令的输出，如果发生错误则返回错误信息。
     */
    public String pingHost(String host) {
        StringBuilder output = new StringBuilder();
        String cleanedHost = host.replaceAll("[;&|`$()]", ""); // Clean input to prevent command injection

        List<String> command = new ArrayList<>();
        String osName = System.getProperty("os.name").toLowerCase();

        if (osName.contains("win")) {
            // Windows command
            command.add("cmd.exe");
            command.add("/c");
            command.add("ping");
            command.add(cleanedHost);
        } else {
            // Unix-like (Linux, macOS) command
            command.add("ping");
            command.add("-c"); // count
            command.add("1");  // ping once
            command.add(cleanedHost);
        }

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true); // Redirect error stream to output stream

        try {
            Process process = processBuilder.start();

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append(System.lineSeparator());
                }
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Ping command failed with exit code: ").append(exitCode).append(System.lineSeparator());
            }

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append(System.lineSeparator());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Ping command was interrupted: ").append(e.getMessage()).append(System.lineSeparator());
        }

        return output.toString();
    }

