        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\nPinging localhost:");
        System.out.println(pinger.pingHost("localhost"));

        System.out.println("\nPinging an invalid host (should fail):");
        System.out.println(pinger.pingHost("invalid.domain.xyz"));

        System.out.println("\nPinging with potential injection attempt (should be cleaned):");
        System.out.println(pinger.pingHost("google.com; ls -l")); // '; ls -l' should be ignored
    }
}
