        // Làm sạch đầu vào để ngăn chặn chèn lệnh
        String sanitizedServerAddress = serverAddress.replaceAll("[;&]", "");
        String sanitizedSignal = signal.replaceAll("[;&]", "");

        if (sanitizedServerAddress.isEmpty() || sanitizedSignal.isEmpty()) {
            System.err.println("Lỗi: Địa chỉ máy chủ hoặc tín hiệu bị trống sau khi làm sạch. Không thể gửi.");
