            /*
            ProcessBuilder processBuilder = new ProcessBuilder("bash", "-c", command);
            Process process = processBuilder.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            System.out.println("Output từ lệnh:");
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            int exitCode = process.waitFor();
            System.out.println("Lệnh thoát với mã: " + exitCode);

            if (exitCode == 0) {
                System.out.println("Tín hiệu đã được gửi thành công (giả định).");
                return true;
            } else {
                System.err.println("Lỗi khi gửi tín hiệu.");
                return false;
            }
            */

            System.out.println("Tín hiệu đã được xử lý và làm sạch. (Không thực sự gửi qua mạng trong ví dụ này).");
            return true; // Giả định thành công cho mục đích minh họa
        } catch (Exception e) { // Bao gồm IOException và InterruptedException nếu dùng ProcessBuilder
            System.err.println("Lỗi khi gửi tín hiệu: " + e.getMessage());
            return false;
        }
    }

    public static void main(String[] args) {
        ClassX sender = new ClassX();

        System.out.println("--- Test 1: Đầu vào an toàn ---");
        sender.sendSignal("192.168.1.100", "status_check"); // An toàn
        System.out.println("\n--- Test 2: Đầu vào độc hại với dấu chấm phẩy ---");
        sender.sendSignal("192.168.1.100", "status_check; rm -rf /"); // Độc hại
        System.out.println("\n--- Test 3: Đầu vào độc hại với dấu & ---");
        sender.sendSignal("192.168.1.100", "status_check & echo hello"); // Độc hại
        System.out.println("\n--- Test 4: Địa chỉ độc hại ---");
        sender.sendSignal("192.168.1.100; evil.com", "status_check"); // Độc hại
        System.out.println("\n--- Test 5: Đầu vào trống sau khi làm sạch ---");
        sender.sendSignal(";", "&"); // Trống sau khi làm sạch
    }
}
