        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be null or empty.";
        }

        // Sanitize the input to prevent command injection
        // Remove common shell metacharacters
        String sanitizedHost = host.trim()
                                   .replace(";", "")
                                   .replace("&", "")
                                   .replace("|", "")
                                   .replace("`", "")
                                   .replace("(", "")
                                   .replace(")", "")
                                   .replace("$", "")
                                   .replace("<", "")
                                   .replace(">", "");

