import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Extrai um arquivo zip para o destino especificado após verificar os caminhos dos membros.
     * 
     * A função itera pelos membros do arquivo e tenta prevenir a travessia de caminhos verificando se o nome do membro contém '..'.
     * Além disso, uma verificação mais robusta é realizada para garantir que os arquivos extraídos permaneçam
     * dentro do diretório de destino especificado, usando caminhos canônicos.
     *
     * @param zipFilePath O caminho completo para o arquivo zip a ser extraído.
     * @param destDirectory O diretório onde o conteúdo do arquivo zip será extraído.
     * @throws IOException Se ocorrer um erro de I/O durante a extração ou se uma tentativa de travessia de caminho for detectada.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // Obtém o caminho canônico do diretório de destino para verificações de segurança
        String canonicalDestDirPath = destDir.getCanonicalPath();

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Itera sobre todos os arquivos e diretórios dentro do arquivo zip
            while (entry != null) {
                String entryName = entry.getName();

                // Prevenção básica de travessia de caminho (conforme solicitado)
                if (entryName.contains("..") || entryName.startsWith("/") || entryName.contains(":\\")) {
                    throw new IOException("Zip entry contains potentially malicious path characters: " + entryName);
                }

                File destFile = new File(destDir, entryName);

                // Verificação de segurança mais robusta usando caminhos canônicos
                // Garante que o arquivo extraído não seja gravado fora do diretório de destino
                String canonicalDestFile = destFile.getCanonicalPath();
                if (!canonicalDestFile.startsWith(canonicalDestDirPath + File.separator) && !canonicalDestFile.equals(canonicalDestDirPath)) {
                    throw new IOException("Zip entry attempts to write outside the target directory: " + entryName);
                }

                if (!entry.isDirectory()) {
                    // Garante que os diretórios pai existam
                    File parent = destFile.getParentFile();
                    if (!parent.exists()) {
                        parent.mkdirs();
                    }
                    // Escreve o arquivo no disco
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[4096];
                        int bytesRead;
                        while ((bytesRead = zipIn.read(buffer)) != -1) {
                            fos.write(buffer, 0, bytesRead);
                        }
                    }
                } else {
                    // Se a entrada for um diretório, cria-o
                    destFile.mkdirs();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
}
