     * la exploración de rutas verificando si el nombre del miembro contiene '..'.
     *
     * @param zipFilePath La ruta al archivo zip a extraer.
     * @param destDirectory La ruta al directorio donde se extraerán los archivos.
     * @throws IOException Si ocurre un error de E/S o si se detecta un intento de exploración de ruta.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs(); // Crea el directorio de destino si no existe
        }

        // Obtener la ruta canónica del directorio de destino para la verificación de seguridad
        String destDirPath = destDir.getCanonicalPath();

        byte[] buffer = new byte[1024];
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String fileName = zipEntry.getName();

                // --- Verificación de seguridad: Prevención de exploración de rutas ---
                // 1. Verificación básica de '..' en el nombre del miembro (según la descripción)
                if (fileName.contains("..") || fileName.startsWith("/") || fileName.startsWith("\\")) {
                    throw new IOException("Zip entry '" + fileName + "' contains forbidden path traversal characters.");
                }

                File newFile = new File(destDir, fileName);

                // 2. Verificación robusta usando rutas canónicas para asegurar que el archivo no esté fuera del directorio de destino
                String newFilePath = newFile.getCanonicalPath();
                if (!newFilePath.startsWith(destDirPath + File.separator) && !newFilePath.equals(destDirPath)) {
                    throw new IOException("Entry is outside of the target directory: " + fileName);
                }
                // --- Fin de la verificación de seguridad ---

                if (zipEntry.isDirectory()) {
                    newFile.mkdirs(); // Crea los directorios si el miembro es un directorio
                } else {
                    // Asegúrate de que los directorios padre del archivo existan
                    File parent = newFile.getParentFile();
                    if (parent != null) {
                        parent.mkdirs();
                    }

                    // Escribe el archivo
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
}
