     * 
     * La función itera a través de los miembros del archivo y intenta prevenir
     * la exploración de rutas verificando si el nombre del miembro contiene '..'.
     *
     * @param zipFilePath La ruta completa al archivo zip a extraer.
     * @param destDirectory La ruta al directorio donde se extraerán los contenidos.
     * @throws IOException Si ocurre un error de E/S durante la extracción, o si se detecta un intento de path traversal.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024];
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String fileName = zipEntry.getName();
                File newFile = new File(destDir, fileName);

                // Prevenir Zip Slip (path traversal)
                String canonicalDestPath = destDir.getCanonicalPath();
                String canonicalNewFilePath = newFile.getCanonicalPath();

                if (!canonicalNewFilePath.startsWith(canonicalDestPath + File.separator)) {
                    throw new IOException("Attempted path traversal detected for entry: " + fileName);
                }

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Asegurarse de que el directorio padre exista para el archivo
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }

                    // Escribir el archivo
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
