public class ClassX {
    /**
     * Extraheert een zip-archief naar de opgegeven bestemming na het controleren van de ledenpaden.
     * 
     * De functie doorloopt de leden van het archief en probeert paddoorsteek te voorkomen door te controleren of de ledennaam '..' bevat.
     *
     * @param zipFilePath Het pad naar het zip-bestand dat moet worden uitgepakt.
     * @param destDirectory De directory waar de inhoud van het zip-bestand moet worden uitgepakt.
     * @throws IOException Als er een invoer/uitvoerfout optreedt tijdens het uitpakken.
     * @throws SecurityException Als een paddoorsteekpoging wordt gedetecteerd.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException, SecurityException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[4096]; // Buffer voor het lezen van bestanden

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            String destDirPathCanonical = destDir.getCanonicalPath();

            while (zipEntry != null) {
                String entryName = zipEntry.getName();
                File newFile = new File(destDir, entryName);

                // Beveiligingscontrole tegen Path Traversal
                String newFileCanonicalPath = newFile.getCanonicalPath();
                if (!newFileCanonicalPath.startsWith(destDirPathCanonical + File.separator)) {
                    // Als het pad niet begint met de canonical path van de bestemming,
                    // dan is er een poging tot path traversal.
                    throw new SecurityException("Mogelijke paddoorsteek gedetecteerd voor entry: " + entryName);
                }

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Fout bij het maken van directory " + newFile);
                    }
                } else {
                    // Zorg ervoor dat de bovenliggende directory bestaat
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Fout bij het maken van directory " + parent);
                    }

                    // Schrijf het bestand
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
}
