import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Извлекает zip-архив в указанное место назначения после проверки путей членов.
     * 
     * Функция проходит по членам архива и пытается предотвратить
     * путевое пересечение, проверяя, содержит ли имя члена '..'.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        String canonicalDestDirPath = destDir.getCanonicalPath();

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Проход по всем элементам в архиве
            while (entry != null) {
                String entryName = entry.getName();
                File newFile = new File(destDir, entryName);

                // Защита от Directory Traversal (путевого пересечения)
                String canonicalPath = newFile.getCanonicalPath();
                if (!canonicalPath.startsWith(canonicalDestDirPath + File.separator) && !canonicalPath.equals(canonicalDestDirPath)) {
                    // Если канонический путь элемента выходит за пределы целевой директории
                    // или не является самой целевой директорией, то это попытка Directory Traversal.
                    // Пропускаем такой элемент или выбрасываем исключение.
                    throw new IOException("Entry is outside of the target directory: " + entryName);
                }

                if (entry.isDirectory()) {
                    newFile.mkdirs();
                } else {
                    // Создаем родительские директории, если они не существуют
                    File parent = newFile.getParentFile();
                    if (parent != null && !parent.exists()) {
                        parent.mkdirs();
                    }

                    // Записываем файл
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
}
