     * @throws SecurityException 如果检测到路径遍历尝试。
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException, SecurityException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // Get the canonical path of the destination directory to prevent path traversal
        Path destDirPath = Paths.get(destDirectory).toRealPath();

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // iterates over entries in the zip file
            while (entry != null) {
