                File filePath = new File(destDir, entryName);

                // IMPORTANT: Path Traversal Vulnerability Check
                // 1. Check for ".." in the entry name
                if (entryName.contains("..")) {
                    throw new SecurityException("Zip entry contains '..' (path traversal attempt): " + entryName);
                }

                // 2. Canonical path check: Ensure the resolved entry path is within the destination directory
                Path resolvedPath = filePath.toPath().toRealPath();
                if (!resolvedPath.startsWith(destDirPath)) {
                    throw new SecurityException("Zip entry attempts to write outside of the destination directory (path traversal attempt): " + entryName);
                }

                if (!entry.isDirectory()) {
                    // if the entry is a file, extract it
                    extractFile(zipIn, filePath);
                } else {
                    // if the entry is a directory, make sure it exists
                    filePath.mkdir();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }

    /**
     * Extracts a zip file entry (file) to a specific destination file.
     *
