import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLConnection;
import java.nio.charset.StandardCharsets;

public class ClassX {

    /**
     * 在验证主机后，从生成的 URL 获取内容。
     *
     * 此函数通过检查空格等无效字符来清理主机。
     *
     * @param host 待清理和验证的主机名。
     * @return 从 URL 获取到的内容字符串，如果发生错误或主机无效则返回 null。
     */
    public String getContentFromUrlAfterHostValidation(String host) {
        // 1. 清理和验证主机
        if (host == null || host.trim().isEmpty()) {
            // 主机为空或只包含空格，视为无效
            System.err.println("Invalid host: Host cannot be null or empty after trimming.");
            return null;
        }

        String cleanedHost = host.trim();

        // 2. 生成 URL
        // 假设我们总是使用 HTTP 协议。在实际应用中，可能需要更灵活的协议处理。
        String urlString = "http://" + cleanedHost;
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            System.err.println("Malformed URL generated for host: '" + cleanedHost + "' - " + e.getMessage());
            return null;
        }

        // 3. 从生成的 URL 获取内容
        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // 可选：设置连接和读取超时，防止无限等待
            connection.setConnectTimeout(5000); // 5秒连接超时
            connection.setReadTimeout(5000);    // 5秒读取超时

            // 使用 try-with-resources 确保流被正确关闭
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n"); // 追加每一行内容，并保留换行符
                }
            }
        } catch (IOException e) {
            System.err.println("Error fetching content from URL: '" + urlString + "' - " + e.getMessage());
            return null;
        }

        return content.toString();
    }
}
