import java.nio.charset.StandardCharsets;

public class ClassX {

    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     * <p>
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     * De host mag niet leeg zijn na het opschonen. De gegenereerde URL gebruikt HTTPS.
     *
     * @param host De hostnaam die moet worden opgeschoond en gevalideerd.
     * @param path Het pad van de URL. Moet beginnen met een '/'. Als dit niet het geval is, wordt er een toegevoegd.
     * @return De inhoud van de URL als een String.
     * @throws IllegalArgumentException Als de host leeg is na opschonen, of als het pad ongeldig is.
     * @throws MalformedURLException Als de gegenereerde URL ongeldig is.
     * @throws IOException Als er een fout optreedt bij het openen van de verbinding of het lezen van de inhoud.
     */
    public String getContentFromValidatedUrl(String host, String path) throws MalformedURLException, IOException {
        // 1. Host opschonen en valideren
        if (host == null) {
            throw new IllegalArgumentException("Host mag niet null zijn.");
        }
        String cleanedHost = host.trim().replaceAll("\\s+", ""); // Verwijder spaties en trim
        if (cleanedHost.isEmpty()) {
            throw new IllegalArgumentException("Host mag niet leeg zijn na opschonen.");
        }

        // 2. Pad voorbereiden
        String finalPath = path;
        if (finalPath == null || finalPath.isEmpty()) {
            finalPath = "/"; // Standaard naar root als pad leeg is
        } else if (!finalPath.startsWith("/")) {
            finalPath = "/" + finalPath; // Zorg ervoor dat het pad met een slash begint
        }

        // 3. URL genereren
        URL url = new URL("https", cleanedHost, finalPath);

        // 4. Inhoud ophalen
        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Optioneel: Stel een timeout in
            connection.setConnectTimeout(5000); // 5 seconden
            connection.setReadTimeout(10000);   // 10 seconden

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append(System.lineSeparator());
                }
            }
        } catch (IOException e) {
            // Voeg context toe aan de uitzondering
            throw new IOException("Fout bij het ophalen van inhoud van URL: " + url.toString(), e);
        }

        return content.toString();
    }
}
