     */
    public String getContentFromValidatedHostUrl(URL url) throws IOException {
        if (url == null) {
            throw new IllegalArgumentException("URL ei tohi olla null.");
        }

        String host = url.getHost();

        // Hosti valideerimine: kontrolli tühikute ja muude keelatud märkide olemasolu.
        // Lihtne reegel: host ei tohi sisaldada tühikuid ja ei tohi olla tühi.
        // Keerukam reegel võiks kasutada täpsemat regexit (RFC 1035, RFC 1123).
        // Siin eeldame, et "puhastamine" tähendab kehtetute hostinimede tagasi lükkamist.
        if (host == null || host.trim().isEmpty() || host.contains(" ")) {
            throw new IllegalArgumentException("URL-i host '" + host + "' on kehtetu. See ei tohi sisaldada tühikuid ega olla tühi.");
        }

        // Täiendav valideerimine: veendumaks, et host on nime või IP-aadressi formaadis
        // See regex kontrollib tavalisi domeeninimesid ja IP-aadresse.
        // See ei ole täiuslik, kuid katab enamiku juhtudest.
        Pattern hostPattern = Pattern.compile(
            "^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,6}|" + // Domeeninimi
            "^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$" // IPv4
        );
        Matcher matcher = hostPattern.matcher(host);
        if (!matcher.matches()) {
            throw new IllegalArgumentException("URL-i host '" + host + "' ei vasta oodatud domeeninime või IP-aadressi formaadile.");
        }

        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Võimalik seadistada ühenduse ajapiiranguid või muid omadusi
            // connection.setConnectTimeout(5000); // 5 sekundit
            // connection.setReadTimeout(10000);  // 10 sekundit

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append(System.lineSeparator());
                }
            }
        } catch (IOException e) {
            // Lisame konteksti veateatele, et oleks lihtsam siluda
            throw new IOException("URL-i sisu toomine ebaõnnestus: " + url.toExternalForm(), e);
        }
        return content.toString();
    }
}
