    /**
     * Lấy nội dung từ một URL đã được tạo ra sau khi xác thực máy chủ.
     * <p>
     * Hàm này làm sạch máy chủ bằng cách kiểm tra các ký tự không hợp lệ như khoảng trắng.
     *
     * @param authenticatedUrl URL đã được xác thực mà từ đó nội dung sẽ được lấy.
     * @return Nội dung của URL dưới dạng chuỗi.
     * @throws IOException Nếu có lỗi I/O xảy ra trong quá trình kết nối hoặc đọc dữ liệu.
     * @throws IllegalArgumentException Nếu host của URL chứa các ký tự không hợp lệ (ví dụ: khoảng trắng).
     */
    public String getContentFromAuthenticatedUrl(URL authenticatedUrl) throws IOException {
        if (authenticatedUrl == null) {
            throw new IllegalArgumentException("URL không được phép là null.");
        }

        String host = authenticatedUrl.getHost();

        // Kiểm tra và làm sạch host: đảm bảo không có ký tự không hợp lệ như khoảng trắng.
        // Việc loại bỏ các ký tự có thể thay đổi ý nghĩa của host,
        // do đó, cách tiếp cận an toàn hơn là xác thực và từ chối nếu không hợp lệ.
        if (host != null && host.contains(" ")) {
            throw new IllegalArgumentException("Host chứa ký tự không hợp lệ (khoảng trắng): " + host);
        }

        StringBuilder content = new StringBuilder();
        try {
            // Mở kết nối đến URL.
            URLConnection connection = authenticatedUrl.openConnection();

            // Thiết lập các thuộc tính kết nối nếu cần (ví dụ: timeout).
            // connection.setConnectTimeout(5000); // 5 giây timeout kết nối
            // connection.setReadTimeout(5000);    // 5 giây timeout đọc dữ liệu

            // Đọc nội dung từ InputStream của kết nối.
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append(System.lineSeparator());
                }
            }
        } catch (IOException e) {
            throw new IOException("Không thể lấy nội dung từ URL: " + authenticatedUrl, e);
        }

        return content.toString();
    }
}
