    public String getUrlContentAfterHostValidation(String host, String path) throws IOException {
        // 1. Host Sanitization and Validation
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("El host no puede ser nulo o vacío.");
        }
        if (host.contains(" ")) {
            throw new IllegalArgumentException("El host contiene caracteres inválidos (espacios).");
        }
