        // for valid domain name characters.

        // 2. URL Construction
        // Assuming HTTP protocol. For HTTPS, adjust accordingly or make it configurable.
        // Ensure the path starts with a '/' for correct URL formation.
        String fullUrlString = "http://" + host + (path.startsWith("/") ? path : "/" + path);
        URL url = new URL(fullUrlString);

        // 3. Content Retrieval
        StringBuilder content = new StringBuilder();

        // Open connection and set a timeout (optional but recommended)
        URLConnection connection = url.openConnection();
        connection.setConnectTimeout(5000); // 5 seconds connection timeout
        connection.setReadTimeout(10000);   // 10 seconds read timeout

