public class ClassX {
    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     * 
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     *
     * @param host Строка, представляющая хост. Будет очищена от пробелов.
     * @param path Путь к ресурсу на хосте.
     * @return Содержимое URL в виде строки.
     * @throws IOException Если возникает ошибка ввода-вывода при подключении или чтении,
     *                     или если URL некорректно сформирован.
     * @throws IllegalArgumentException Если хост становится пустым после очистки.
     */
    public String getContentFromUrl(String host, String path) throws IOException {
        // Очистка хоста: удаление всех пробельных символов.
        // Это соответствует задаче "проверяя наличие недопустимых символов, таких как пробелы".
        String cleanedHost = host.replaceAll("\\s+", "");

        if (cleanedHost.isEmpty()) {
            throw new IllegalArgumentException("Host cannot be empty after cleaning.");
        }

        URL url;
        try {
            // Используем протокол "http" по умолчанию, так как он не указан в задаче.
            // Для более гибкого решения протокол можно было бы передавать как параметр.
            url = new URL("http", cleanedHost, path);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Failed to construct URL with cleaned host '" + cleanedHost + "' and path '" + path + "': " + e.getMessage());
        }

        StringBuilder content = new StringBuilder();
        BufferedReader reader = null;
        try {
            URLConnection connection = url.openConnection();
            // Установка таймаутов для подключения и чтения данных
            connection.setConnectTimeout(5000); // 5 секунд
            connection.setReadTimeout(5000);    // 5 секунд

            reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Логирование ошибки при закрытии, чтобы не скрыть основное исключение
                    System.err.println("Error closing BufferedReader: " + e.getMessage());
                }
            }
        }
        return content.toString();
    }
}
