public class ClassX {
    /**
     * Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.
     *
     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     *
     * @param host Der Hostname, der validiert und für die URL-Generierung verwendet werden soll.
     * @param path Der Pfad, der an den Host angehängt werden soll, um die vollständige URL zu bilden.
     * @return Eine URL, die mit dem validierten Host und dem gegebenen Pfad generiert wurde.
     * @throws IllegalArgumentException Wenn der Host null, leer ist oder ungültige Zeichen wie Leerzeichen enthält.
     * @throws MalformedURLException Wenn die generierte URL syntaktisch inkorrekt ist.
     */
    public URL getValidatedUrl(String host, String path) throws MalformedURLException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }

        String cleanedHost = host.trim();

        // Check for spaces within the host string, as trimming only removes leading/trailing spaces.
        if (cleanedHost.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid spaces.");
        }

        // Construct the URL using a secure protocol (e.g., HTTPS).
        // The URL constructor itself performs further validation on the host format.
        return new URL("https", cleanedHost, path);
    }
}
