     * تقوم هذه الوظيفة بتنظيف المضيف من خلال التحقق من وجود أحرف غير صالحة مثل المسافات.
     *
     * @param protocol بروتوكول URL (مثل "http" أو "https").
     * @param host المضيف لعنوان URL. يتم التحقق من صحة هذا المضيف وتنظيفه.
     * @param port المنفذ لعنوان URL.
     * @param path المسار لعنوان URL.
     * @return محتوى URL كسلسلة نصية.
     * @throws IllegalArgumentException إذا كان المضيف غير صالح (يحتوي على مسافات أو فارغ).
     * @throws MalformedURLException إذا تعذر إنشاء URL صالح.
     * @throws IOException إذا حدث خطأ أثناء فتح الاتصال أو قراءة المحتوى.
     */
    public String retrieveContent(String protocol, String host, int port, String path)
            throws IllegalArgumentException, MalformedURLException, IOException {

        // التحقق من صحة المضيف: التأكد من أنه ليس فارغًا ولا يحتوي على مسافات.
        if (host == null || host.trim().isEmpty() || host.contains(" ")) {
            throw new IllegalArgumentException("Host cannot be null, empty, or contain spaces.");
        }
        String cleanedHost = host.trim();

        // بناء كائن URL
        URL url = new URL(protocol, cleanedHost, port, path);

        // فتح اتصال وقراءة المحتوى
        URLConnection connection = url.openConnection();
        // تعيين مهلة للاتصال والقراءة لتجنب التعليق
        connection.setConnectTimeout(5000); // 5 ثوانٍ
        connection.setReadTimeout(5000);    // 5 ثوانٍ

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
                content.append(System.lineSeparator()); // الحفاظ على فواصل الأسطر
            }
        }
        return content.toString();
    }
