    /**
     * Simula a função mailcap.findmatch. 
     * Constrói um comando para visualizar o arquivo com base no mime_type e o executa.
     * 
     * Esta implementação inclui uma verificação para evitar a cadeia de comandos, bloqueando 
     * pontos e vírgulas.
     *
     * @param mimeType O tipo MIME do arquivo (ex: "text/plain", "image/jpeg").
     * @param filePath O caminho completo para o arquivo a ser visualizado.
     */
    public static void viewFile(String mimeType, String filePath) {
        // --- Prevenção de Injeção de Comando: Bloqueio de Ponto e Vírgula ---
        if (mimeType.contains(";") || filePath.contains(";")) {
            System.err.println("ERRO: Caracteres de ponto e vírgula (;) não são permitidos no tipo MIME ou no caminho do arquivo por motivos de segurança.");
            return;
        }

        String commandTemplate;

        // Mapeia o tipo MIME para um comando de visualização
        switch (mimeType.toLowerCase()) {
            case "text/plain":
            case "text/html":
                commandTemplate = "less \"%s\""; // Usar 'less' para texto, aspas para espaços no nome do arquivo
                break;
            case "image/jpeg":
            case "image/png":
            case "image/gif":
                commandTemplate = "xdg-open \"%s\""; // xdg-open é genérico para ambientes desktop Linux
                // Alternativa mais específica: "eog \"%s\"" (Eye of GNOME)
                break;
            case "application/pdf":
                commandTemplate = "xdg-open \"%s\""; // xdg-open para PDFs
                // Alternativa mais específica: "evince \"%s\""
                break;
            // Adicione mais mapeamentos conforme necessário
            default:
                System.out.println("AVISO: Tipo MIME desconhecido ou não mapeado (" + mimeType + "). Tentando com 'xdg-open'.");
                commandTemplate = "xdg-open \"%s\""; // Fallback para um visualizador genérico
                break;
        }

        // Constrói o comando final
        // As aspas em '%s' são para lidar com nomes de arquivo que contenham espaços.
        String fullCommand = String.format(commandTemplate, filePath);

        System.out.println("Executando comando: " + fullCommand);

        try {
            // Executa o comando
            Process process = Runtime.getRuntime().exec(fullCommand);

            // Lê a saída padrão do processo (stdout)
            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String s;
            while ((s = stdInput.readLine()) != null) {
                System.out.println("Saída: " + s);
            }

            // Lê a saída de erro padrão do processo (stderr)
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((s = stdError.readLine()) != null) {
                System.err.println("Erro do comando: " + s);
            }

            // Espera o processo terminar e obtém o código de saída
            int exitCode = process.waitFor();
            System.out.println("Comando " + (exitCode == 0 ? "executado com sucesso." : "falhou com código de saída " + exitCode + "."));

        } catch (IOException e) {
            System.err.println("ERRO ao executar comando: " + e.getMessage());
            e.printStackTrace();
        } catch (InterruptedException e) {
            System.err.println("ERRO: O processo foi interrompido: " + e.getMessage());
            Thread.currentThread().interrupt(); // Restaura o status de interrupção
        }
    }

