     */
    public boolean displayFile(String mimeType, String filePath) {
        if (mimeType == null || filePath == null || mimeType.contains(";") || filePath.contains(";")) {
            System.err.println("Invalid input: mimeType or filePath contains forbidden characters (e.g., semicolons).");
            return false;
