        String command = null;

        if (mimeType.startsWith("text/")) {
            command = "less " + filePath; // Example for text files
        } else if (mimeType.startsWith("image/")) {
            command = "display " + filePath; // Example for image files (requires ImageMagick or similar)
        } else if (mimeType.equals("application/pdf")) {
            command = "evince " + filePath; // Example for PDF files
        } else {
            System.err.println("No viewer configured for MIME type: " + mimeType);
            return false;
        }

        System.out.println("Executing command: " + command);

        try {
            Process process = Runtime.getRuntime().exec(command);

            // Capture output and error streams (optional, but good practice)
            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String s;
            System.out.println("Standard output of the command:\n");
            while ((s = stdInput.readLine()) != null) {
                System.out.println(s);
            }

            System.out.println("Standard error of the command:\n");
            while ((s = stdError.readLine()) != null) {
                System.err.println(s);
            }

            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);

            return exitCode == 0; // Return true if command executed successfully

        } catch (IOException e) {
            System.err.println("Error executing command: " + e.getMessage());
            e.printStackTrace();
        } catch (InterruptedException e) {
            System.err.println("Command execution interrupted: " + e.getMessage());
            Thread.currentThread().interrupt(); // Restore the interrupted status
        }
        return false;
    }

    // Example main method to demonstrate usage
