import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Προσομοιώνει τη λειτουργία mailcap.findmatch.
     * Κατασκευάζει μια εντολή για να δει το αρχείο με βάση τον mime_type και την εκτελεί.
     *
     * Αυτή η υλοποίηση περιλαμβάνει έναν έλεγχο για να αποτρέψει την αλυσίδωση εντομών αποκλείοντας τα ερωτηματικά.
     *
     * @param mimeType Ο τύπος MIME του αρχείου προς προβολή.
     * @param filePath Η διαδρομή προς το αρχείο.
     * @return Ένα String που περιέχει την έξοδο της εκτελούμενης εντολής, ή null σε περίπτωση σφάλματος.
     */
    public String findAndExecuteMatch(String mimeType, String filePath) {
        // Αποτροπή αλυσίδωσης εντολών: Αποκλεισμός του ερωτηματικού (;)
        // Πρόσθετοι χαρακτήρες που θα μπορούσαν να χρησιμοποιηθούν για αλυσίδωση εντολών είναι:
        // &&, ||, &, |, <, >, ` (backtick), $ (για υποκατάσταση μεταβλητών)
        // Για μια πιο ολοκληρωμένη προστασία, θα πρέπει να γίνει whitelisting των επιτρεπόμενων χαρακτήρων
        // ή να χρησιμοποιηθεί μια βιβλιοθήκη που χειρίζεται την εκτέλεση εξωτερικών διεργασιών με ασφάλεια.
        if (mimeType == null || filePath == null ||
            mimeType.contains(";") || filePath.contains(";") ||
            mimeType.contains("&&") || filePath.contains("&&") ||
            mimeType.contains("||") || filePath.contains("||") ||
            mimeType.contains("&") || filePath.contains("&") ||
            mimeType.contains("|") || filePath.contains("|") ||
            mimeType.contains("<") || filePath.contains("<") ||
            mimeType.contains(">") || filePath.contains(">") ||
            mimeType.contains("`") || filePath.contains("`") ||
            mimeType.contains("$") || filePath.contains("$")) {
            System.err.println("Error: Invalid characters detected in mimeType or filePath. Command chaining attempt prevented.");
            return null;
        }

        String command = "";
        // Βασική, απλοϊκή αντιστοίχιση mime_type σε εντολή προβολής
        // Σε μια πραγματική εφαρμογή, αυτό θα έπρεπε να διαβάζεται από ένα αρχείο mailcap
        // ή μια βάση δεδομένων ρυθμίσεων.
        switch (mimeType) {
            case "text/plain":
                command = "cat " + filePath;
                break;
            case "image/jpeg":
            case "image/png":
                command = "xdg-open " + filePath; // Ή "eog", "display", "feh" κλπ. ανάλογα με το σύστημα
                break;
            case "application/pdf":
                command = "xdg-open " + filePath; // Ή "evince", "okular", "acroread"
                break;
            case "text/html":
                command = "xdg-open " + filePath; // Ή "firefox", "chromium"
                break;
            default:
                System.err.println("Unsupported MIME type: " + mimeType);
                return null;
        }

        StringBuilder output = new StringBuilder();
        try {
            Process process = Runtime.getRuntime().exec(command);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                System.err.println("Command Error: " + errorLine);
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                System.err.println("Command exited with error code: " + exitCode);
                return null;
            }

        } catch (IOException e) {
            System.err.println("IOException during command execution: " + e.getMessage());
            e.printStackTrace();
            return null;
        } catch (InterruptedException e) {
            System.err.println("Command execution was interrupted: " + e.getMessage());
            Thread.currentThread().interrupt(); // Restore the interrupted status
            return null;
        }

        return output.toString();
    }

