        ClassX mailcapSimulator = new ClassX();

        System.out.println("--- Testing text/plain ---");
        String textOutput = mailcapSimulator.findAndExecuteMatch("text/plain", "/etc/os-release");
        if (textOutput != null) {
            System.out.println("Output for text/plain:\n" + textOutput);
        } else {
            System.out.println("Failed to process text/plain.");
        }

        System.out.println("\n--- Testing image/jpeg (should open viewer if xdg-open is available) ---");
        // Δημιουργήστε ένα ψεύτικο αρχείο εικόνας για δοκιμή
        // Σημείωση: Αυτό απλά θα προσπαθήσει να ανοίξει ένα αρχείο, δεν θα παράγει έξοδο στο stdout
        // Αν δεν υπάρχει αρχείο, το xdg-open μπορεί να αποτύχει σιωπηλά ή με ένα σφάλμα στην stderr.
        // Για πραγματική δοκιμή, χρειάζεται ένα υπάρχον αρχείο εικόνας.
        String imageOutput = mailcapSimulator.findAndExecuteMatch("image/jpeg", "/tmp/non_existent_image.jpg");
        if (imageOutput != null) {
            System.out.println("Output for image/jpeg (may be empty if viewer opened successfully):\n" + imageOutput);
        } else {
            System.out.println("Failed to process image/jpeg (expected if file doesn't exist or viewer fails).");
        }

        System.out.println("\n--- Testing with command injection attempt (should be blocked) ---");
        // Προσπάθεια injection με ερωτηματικό
        String injectedOutput1 = mailcapSimulator.findAndExecuteMatch("text/plain", "/etc/passwd; echo HACKED");
        if (injectedOutput1 == null) {
            System.out.println("Injection attempt with ';' successfully blocked.");
        }

        // Προσπάθεια injection με &&
        String injectedOutput2 = mailcapSimulator.findAndExecuteMatch("text/plain", "/etc/passwd && echo HACKED");
        if (injectedOutput2 == null) {
            System.out.println("Injection attempt with '&&' successfully blocked.");
        }

        // Προσπάθεια injection με |
        String injectedOutput3 = mailcapSimulator.findAndExecuteMatch("text/plain", "/etc/passwd | echo HACKED");
        if (injectedOutput3 == null) {
            System.out.println("Injection attempt with '|' successfully blocked.");
        }

        System.out.println("\n--- Testing unsupported MIME type ---");
        String unsupportedOutput = mailcapSimulator.findAndExecuteMatch("application/x-unknown", "/tmp/file.xyz");
        if (unsupportedOutput == null) {
            System.out.println("Unsupported MIME type correctly handled.");
        }
    }
}
