import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Simuliert die Funktion mailcap.findmatch. 
     * Konstruiert einen Befehl, um die Datei basierend auf dem mime_type anzuzeigen, und führt ihn aus.
     * 
     * Diese Implementierung enthält eine Überprüfung, um das Verketten von Befehlen zu verhindern, indem Semikolons blockiert werden.
     * 
     * @param mimeType Der MIME-Typ der Datei.
     * @param filePath Der Pfad zur anzuzeigenden Datei.
     * @throws IOException Wenn ein E/A-Fehler auftritt.
     * @throws InterruptedException Wenn der externe Prozess unterbrochen wird.
     * @throws SecurityException Wenn der mimeType oder filePath ungültige Zeichen enthält.
     */
    public void findAndExecuteMatch(String mimeType, String filePath) throws IOException, InterruptedException {
        // Überprüfung auf Semikolons, um Befehlsverkettung zu verhindern
        if (mimeType.contains(";") || filePath.contains(";")) {
            throw new SecurityException("Ungültige Zeichen im MIME-Typ oder Dateipfad: Semikolons sind nicht erlaubt.");
        }

        String command;
        // Einfache Zuordnung von MIME-Typen zu Befehlen (Beispielhaft)
        // In einer echten Implementierung würde dies komplexer sein und aus einer Konfigurationsdatei gelesen werden.
        switch (mimeType) {
            case "text/plain":
                command = "cat " + filePath;
                break;
            case "image/jpeg":
            case "image/png":
                command = "xdg-open " + filePath; // Für Linux-Systeme
                // Für Windows: command = "cmd /c start " + filePath;
                // Für macOS: command = "open " + filePath;
                break;
            case "application/pdf":
                command = "xdg-open " + filePath; // Oder ein spezifischer PDF-Viewer wie "evince", "acroread"
                break;
            default:
                System.out.println("Kein passender Viewer für den MIME-Typ '" + mimeType + "' gefunden. Versuche xdg-open.");
                command = "xdg-open " + filePath;
                break;
        }

        System.out.println("Führe Befehl aus: " + command);

        Process process = Runtime.getRuntime().exec(command);

        // Ausgabe des Standard-Outputs des Prozesses
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }

        // Ausgabe des Standard-Error-Outputs des Prozesses
        try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                System.err.println("Fehler: " + errorLine);
            }
        }

        int exitCode = process.waitFor();
        System.out.println("Befehl beendet mit Exit-Code: " + exitCode);

        if (exitCode != 0) {
            throw new IOException("Befehlsausführung fehlgeschlagen mit Exit-Code: " + exitCode);
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Beispielaufrufe
        try {
            System.out.println("--- Test 1: Textdatei anzeigen ---");
            // Erstelle eine temporäre Datei für den Test
            java.nio.file.Path tempFile1 = java.nio.file.Files.createTempFile("testfile", ".txt");
            java.nio.file.Files.write(tempFile1, "Dies ist ein Testtext.\nZeile 2.".getBytes());
            classX.findAndExecuteMatch("text/plain", tempFile1.toString());
            java.nio.file.Files.deleteIfExists(tempFile1); // Aufräumen

