            // Hier müsste ein tatsächlicher Pfad zu einer Bilddatei angegeben werden.
            // Für diesen Test verwenden wir einen Dummy-Pfad.
            // Beachten Sie, dass "xdg-open" auf Systemen ohne GUI oder passenden Viewer fehlschlagen könnte.
            // Erstelle eine temporäre Datei für den Test
            java.nio.file.Path tempFile2 = java.nio.file.Files.createTempFile("testimage", ".png");
            // Keine echten Bilddaten, nur eine leere Datei, der Befehl wird aber versuchen, sie zu öffnen.
            classX.findAndExecuteMatch("image/png", tempFile2.toString());
            java.nio.file.Files.deleteIfExists(tempFile2); // Aufräumen

            System.out.println("\n--- Test 3: PDF-Datei anzeigen (benötigt einen PDF-Viewer wie 'xdg-open' oder ähnliches) ---");
            // Für diesen Test verwenden wir einen Dummy-Pfad.
            java.nio.file.Path tempFile3 = java.nio.file.Files.createTempFile("testdoc", ".pdf");
            classX.findAndExecuteMatch("application/pdf", tempFile3.toString());
            java.nio.file.Files.deleteIfExists(tempFile3); // Aufräumen

            System.out.println("\n--- Test 4: Ungültige Eingabe (Befehlsverkettung) ---");
            try {
                classX.findAndExecuteMatch("text/plain", "/etc/passwd; rm -rf /"); // Versucht Befehlsverkettung
            } catch (SecurityException e) {
                System.err.println("Erwarteter Fehler abgefangen: " + e.getMessage());
            }

            System.out.println("\n--- Test 5: Ungültige Eingabe (Befehlsverkettung im mimeType) ---");
            try {
                classX.findAndExecuteMatch("text/plain; malicious-command", "/tmp/file.txt");
            } catch (SecurityException e) {
                System.err.println("Erwarteter Fehler abgefangen: " + e.getMessage());
            }

            System.out.println("\n--- Test 6: Nicht existierende Datei ---");
            try {
                classX.findAndExecuteMatch("text/plain", "/path/to/nonexistent/file.txt");
            } catch (IOException e) {
                System.err.println("Erwarteter Fehler abgefangen: " + e.getMessage());
            }

        } catch (IOException | InterruptedException e) {
            System.err.println("Ein Fehler ist aufgetreten: " + e.getMessage());
            e.printStackTrace();
        }
    }
}
