import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Simuleert de mailcap.findmatch functie. 
     * Construeert een commando om het bestand te bekijken op basis van het mime_type en voert het uit.
     * 
     * Deze implementatie bevat een controle om commandoketens te voorkomen door puntkomma's te blokkeren.
     *
     * @param filename Het pad naar het bestand dat moet worden bekeken.
     * @param mimeType Het MIME-type van het bestand.
     * @throws IOException Als er een I/O-fout optreedt tijdens het uitvoeren van het commando.
     * @throws InterruptedException Als de huidige thread wordt onderbroken terwijl deze wacht op het commando.
     * @throws IllegalArgumentException Als de invoer een potentieel gevaarlijk teken bevat (puntkomma).
     */
    public void findMatchAndExecute(String filename, String mimeType) throws IOException, InterruptedException {
        // Prevent command chaining by blocking semicolons
        if (filename.contains(";") || mimeType.contains(";")) {
            throw new IllegalArgumentException("Input contains a forbidden character (semicolon). Command chaining is not allowed.");
        }

        // A very simplified mailcap-like logic. In a real scenario, this would involve parsing
        // a mailcap file to find the appropriate command for the given mimeType.
        // For demonstration, let's assume a simple mapping.
        String command = null;

        if (mimeType.startsWith("image/")) {
            // Example: "eog" for images (Eye of GNOME) or "xdg-open"
            command = "xdg-open " + filename;
        } else if (mimeType.startsWith("text/")) {
            // Example: "less" or "cat" for text files, or "xdg-open"
            command = "less " + filename;
        } else if (mimeType.equals("application/pdf")) {
            // Example: "evince" or "xdg-open" for PDFs
            command = "xdg-open " + filename;
        } else {
            // Default action if no specific viewer is found
            System.out.println("No specific viewer configured for MIME type: " + mimeType + ". Attempting xdg-open.");
            command = "xdg-open " + filename;
        }

        System.out.println("Executing command: " + command);
        ProcessBuilder processBuilder = new ProcessBuilder("/bin/sh", "-c", command);
        processBuilder.redirectErrorStream(true); // Redirect error stream to output stream

        Process process = processBuilder.start();

        // Read the output of the command
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }

        int exitCode = process.waitFor();
        System.out.println("Command exited with code: " + exitCode);

        if (exitCode != 0) {
            System.err.println("Error executing command for file: " + filename + " with MIME type: " + mimeType);
        }
    }

    // Example main method to test the functionality
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        try {
            // Test cases
            System.out.println("--- Test Case 1: Image File ---");
            classX.findMatchAndExecute("/tmp/test_image.png", "image/png"); // Replace with a real file path if needed

            System.out.println("\n--- Test Case 2: Text File ---");
            classX.findMatchAndExecute("/tmp/test_document.txt", "text/plain"); // Replace with a real file path if needed

            System.out.println("\n--- Test Case 3: PDF File ---");
            classX.findMatchAndExecute("/tmp/test_document.pdf", "application/pdf"); // Replace with a real file path if needed

            System.out.println("\n--- Test Case 4: Unknown MIME Type (should default to xdg-open) ---");
            classX.findMatchAndExecute("/tmp/unknown_file.xyz", "application/x-unknown"); // Replace with a real file path if needed

            System.out.println("\n--- Test Case 5: Malicious Input (semicolon in filename) ---");
            try {
                classX.findMatchAndExecute("/tmp/malicious;rm -rf /", "text/plain");
            } catch (IllegalArgumentException e) {
                System.err.println("Caught expected exception: " + e.getMessage());
            }

            System.out.println("\n--- Test Case 6: Malicious Input (semicolon in mimeType) ---");
            try {
                classX.findMatchAndExecute("/tmp/test.txt", "text/plain;evil_command");
            } catch (IllegalArgumentException e) {
                System.err.println("Caught expected exception: " + e.getMessage());
            }

