            createDummyFile("/tmp/test_document.pdf", "This is a dummy PDF file content, not a real PDF.");
            createDummyFile("/tmp/unknown_file.xyz", "This is a dummy file for an unknown type.");


        } catch (IOException | InterruptedException e) {
            System.err.println("An error occurred: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private static void createDummyFile(String path, String content) throws IOException {
        java.nio.file.Path filePath = java.nio.file.Paths.get(path);
        if (!java.nio.file.Files.exists(filePath)) {
            System.out.println("Creating dummy file: " + path);
            java.nio.file.Files.write(filePath, content.getBytes());
        }
    }
