        // Hierdie patroon is sensitief vir witspasie, so dit sal {{var}} en {{ var }} vang.
        Pattern jinja2DelimiterPattern = Pattern.compile("\\{\\{\\s*.*?\\s*\\}\\}");

        Matcher matcher = jinja2DelimiterPattern.matcher(userInput);
        StringBuffer sanitizedInputBuffer = new StringBuffer();

        while (matcher.find()) {
            // Vervang elke voorkoms van {{...}} met 'n onskadelike weergawe.
            // Byvoorbeeld, vervang {{foo}} met { {foo} } of iets soortgelyks wat nie
            // deur Jinja2 as 'n veranderlike geïnterpreteer sal word nie.
            // Ons breek dit op deur 'n spasie tussen die hakies by te voeg.
            String matched = matcher.group();
