            matcher.appendReplacement(sanitizedInputBuffer, Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(sanitizedInputBuffer);

        String sanitizedInput = sanitizedInputBuffer.toString();

        // Verdere sanitasie kan hier bygevoeg word, afhangende van die spesifieke sjabloon-enjin
        // en die tipe aanvalle wat voorkom wil word (bv. XSS, SQL-inspuiting indien die sjabloon
