        // Die maklikste manier om dit te "blokkeer" is om dit te verwyder of te vervang met iets onskadelik.
        String sanitizedInput = matcher.replaceAll(""); // Verwyder die afgrenzers heeltemal

        // 'n Alternatief sou wees om spesifieke gevaarlike karakters te ontsnap.
