public class ClassX {
    private static final Set<String> DANGEROUS_KEYWORDS = new HashSet<>(Arrays.asList(
            "import", "java", "system", "runtime", "class", "function", "object",
            "prototype", "eval", "require", "module", "process", "window", "document",
            "this", "new", "var", "let", "const", "while", "for", "if", "else", "try",
            "catch", "finally", "throw", "return", "delete", "typeof", "instanceof",
            "void", "debugger", "with", "yield"
    ));

    private final ScriptEngine scriptEngine;

    public ClassX() {
        ScriptEngineManager manager = new ScriptEngineManager();
        this.scriptEngine = manager.getEngineByName("nashorn"); // Or "js" for older JDKs/GraalVM
        if (this.scriptEngine == null) {
            throw new IllegalStateException("Nashorn (JavaScript) engine not found. Ensure you are using a compatible JDK or add GraalVM JS engine.");
        }
    }

    /**
     * Analiza y evalúa una expresión matemática del usuario.
     *
     * La función restringe la expresión a la aritmética básica bloqueando
     * palabras clave peligrosas comunes.
     *
     * @param expression La expresión matemática a evaluar.
     * @return El resultado de la evaluación como un Double.
     * @throws IllegalArgumentException Si la expresión contiene palabras clave peligrosas, está vacía,
     *                                  es nula, o no es una expresión matemática válida.
     */
    public Double evaluateExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("La expresión no puede ser nula o vacía.");
        }

        String lowerCaseExpression = expression.toLowerCase();

        // Restricción de palabras clave peligrosas
        for (String keyword : DANGEROUS_KEYWORDS) {
            if (lowerCaseExpression.contains(keyword)) {
                throw new IllegalArgumentException("La expresión contiene una palabra clave peligrosa: '" + keyword + "'");
            }
        }

        try {
            // Evaluar la expresión
            Object result = scriptEngine.eval(expression);

            if (result instanceof Number) {
                return ((Number) result).doubleValue();
