            throw new IllegalArgumentException("Error al evaluar la expresión: " + e.getMessage(), e);
        } catch (Exception e) {
            // Captura otras excepciones inesperadas durante la evaluación
            throw new IllegalArgumentException("Ocurrió un error inesperado al evaluar la expresión: " + e.getMessage(), e);
        }
    }
}
