import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Analizza e valuta un'espressione matematica fornita dall'utente.
     * 
     * La funzione limita l'espressione all'aritmetica di base bloccando parole chiave pericolose comuni.
     *
     * @param expression L'espressione matematica da valutare (e.g., "2 * (3 + 5)").
     * @return Il risultato della valutazione dell'espressione come Double.
     * @throws IllegalArgumentException Se l'espressione è nulla, vuota, o contiene parole chiave pericolose.
     * @throws ScriptException Se si verifica un errore durante la valutazione dell'espressione,
     *                         o se il motore di script non è disponibile.
     */
    public Double evaluateExpression(String expression) throws ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("L'espressione non può essere nulla o vuota.");
        }

        // Lista di parole chiave pericolose da bloccare (case-insensitive)
        // Queste parole chiave sono comuni in JavaScript e potrebbero essere usate per eseguire codice arbitrario.
        String[] dangerousKeywords = {
            "System", "Runtime", "exec", "import", "java", "javax", "class", "new", "function",
            "eval", "while", "for", "if", "switch", "try", "catch", "throw", "return",
            "var", "let", "const", "window", "document", "this", "console", "process",
            "require", "module", "global", "setTimeout", "setInterval", "XMLHttpRequest",
            "fetch", "alert", "prompt", "confirm", "reflect", "proxy", "promise", "map",
            "set", "json", "date", "regexp", "error"
        };

        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : dangerousKeywords) {
            // Controlla se la keyword è presente come parola intera o come parte di una parola per maggiore sicurezza
            if (lowerCaseExpression.matches(".*\\b" + keyword.toLowerCase() + "\\b.*") || lowerCaseExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("L'espressione contiene una parola chiave pericolosa: " + keyword);
            }
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Utilizza il motore JavaScript integrato in Java

        if (engine == null) {
            throw new ScriptException("Motore di script JavaScript non trovato. Assicurati che l'ambiente JRE sia configurato correttamente.");
        }

        Object result = engine.eval(expression);

        if (result instanceof Number) {
            return ((Number) result).doubleValue();
        } else if (result != null) {
            // Se il motore di script restituisce un tipo non numerico ma convertibile, prova a convertirlo.
            // Questo potrebbe accadere con espressioni come "true" o "false", che dovrebbero essere bloccate
            // se si vuole solo aritmetica. Per scopi puramente numerici, questo blocco potrebbe non essere necessario.
            try {
                return Double.parseDouble(result.toString());
            } catch (NumberFormatException e) {
                throw new ScriptException("Il risultato dell'espressione non è un numero valido: " + result, e);
            }
        } else {
            throw new ScriptException("L'espressione non ha prodotto alcun risultato.");
        }
    }
}
