     */
    public static String evaluateExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return "错误: 表达式不能为空。";
        }

        // 定义禁止使用的关键词列表，以防止代码注入和限制为纯数学运算
        // 注意：黑名单方法可能不完全安全，更安全的做法是白名单允许的字符和操作符。
        // 但根据题目要求"阻止常见的危险关键词"，此处采用黑名单方式。
        List<String> forbiddenKeywords = Arrays.asList(
                "import", "java", "Packages", "load", "loadWithNewGlobal",
                "exit", "quit", "System", "Runtime", "process", "debugger",
                "function", "var", "let", "const", "if", "else", "while",
                "for", "switch", "try", "catch", "throw", "new", "this",
                "window", "document", "eval", "setTimeout", "setInterval",
                "require", "console", "Promise", "Array", "Object", "Function",
                "Date", "Math.sin", "Math.cos", "Math.tan", "Math.log", "Math.pow" // 限制为基本算术，排除更复杂的数学函数
        );

        String lowerCaseExpression = expression.toLowerCase();

        for (String keyword : forbiddenKeywords) {
            // 使用正则表达式进行更精确的匹配，避免匹配到单词的一部分
            // 例如，"var" 不会匹配到 "variable"
            if (lowerCaseExpression.matches(".*\\b" + keyword.toLowerCase() + "\\b.*")) {
                return "错误: 表达式包含禁止的关键词或操作符: '" + keyword + "'。只允许基本算术。";
