            return "错误: 表达式包含非法的字符。只允许数字、+、-、*、/、%、(、) 和小数点。";
        }


        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // 使用Rhino/Nashorn JavaScript引擎

        if (engine == null) {
            return "错误: 无法找到JavaScript脚本引擎。请确保您的JRE支持它。";
        }

        try {
            Object result = engine.eval(expression);
            return String.valueOf(result);
        } catch (ScriptException e) {
            return "错误: 无效的数学表达式。请检查语法。" + e.getMessage();
        } catch (Exception e) {
            // 捕获其他潜在的运行时异常
            return "错误: 评估表达式时发生未知错误。" + e.getMessage();
        }
    }
}
