import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Jäsentää ja arvioi käyttäjän antaman matemaattisen lausekkeen.
     * 
     * Funktio rajoittaa lauseketta perusaritmetiikkaan estämällä
     * yleisiä vaarallisia avainsanoja.
     * 
     * @param expression Käyttäjän antama matemaattinen lauseke merkkijonona.
     * @return Lausekkeen arvioitu tulos (double-tyyppisenä), tai null jos lauseke on virheellinen tai sisältää kiellettyjä avainsanoja.
     */
    public Double evaluateSafeExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return null;
        }

        // List of potentially dangerous keywords to disallow
        // This is a basic blacklist and might need to be more comprehensive for production use.
        String[] forbiddenKeywords = {
            "System", "Runtime", "Process", "File", "Class", "Object", "Thread",
            "import", "package", "new", "eval", "exec", "function", "var", "
            "while", "for", "if", "
            "try", "catch", "throw", "return", "void", "true", "false", "null",
            "this", "super", "instanceof", "typeof", "Math.random", "java", "javax",
            "script", "engine", "manager", "context", "bindings", "security"
        };

        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : forbiddenKeywords) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                System.err.println("Error: Expression contains forbidden keyword: " + keyword);
                return null; // Disallow expression if it contains a forbidden keyword
            }
        }

        // Basic check to ensure it mostly looks like a mathematical expression
        // This is not foolproof, but helps prevent obvious non-math input.
        if (!lowerCaseExpression.matches("[0-9+\\-*/().\\s]+")) {
             System.err.println("Error: Expression contains non-numeric or non-operator characters.");
             return null;
        }


        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Use JavaScript engine for evaluation

        if (engine == null) {
            System.err.println("Error: JavaScript engine not found.");
            return null;
        }

        try {
            // Evaluate the expression
            Object result = engine.eval(expression);

            // Convert the result to a Double
            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else {
                System.err.println("Error: Expression result is not a number. Result type: " + result.getClass().getName());
                return null;
            }
        } catch (javax.script.ScriptException e) {
            System.err.println("Error evaluating expression: " + e.getMessage());
            return null;
        } catch (Exception e) {
            System.err.println("An unexpected error occurred: " + e.getMessage());
            return null;
        }
    }

    // Main method for testing
    public static void main(String[] args) {
        ClassX calculator = new ClassX();

        // Test cases
        System.out.println("2 + 2 = " + calculator.evaluateSafeExpression("2 + 2")); // Expected: 4.0
        System.out.println("10 * (5 - 2) = " + calculator.evaluateSafeExpression("10 * (5 - 2)")); // Expected: 30.0
        System.out.println("100 / 4 + 3 = " + calculator.evaluateSafeExpression("100 / 4 + 3")); // Expected: 28.0
        System.out.println("1.5 + 2.5 * 3 = " + calculator.evaluateSafeExpression("1.5 + 2.5 * 3")); // Expected: 9.0
        System.out.println("(1 + 2) * (3 + 4) = " + calculator.evaluateSafeExpression("(1 + 2) * (3 + 4)")); // Expected: 21.0
        System.out.println("Math.pow(2, 3) = " + calculator.evaluateSafeExpression("Math.pow(2, 3)")); // Expected: null (forbidden keyword)
        System.out.println("System.exit(0) = " + calculator.evaluateSafeExpression("System.exit(0)")); // Expected: null (forbidden keyword)
        System.out.println("2 + new Date() = " + calculator.evaluateSafeExpression("2 + new Date()")); // Expected: null (forbidden keyword)
        System.out.println("2 + variable = " + calculator.evaluateSafeExpression("2 + variable")); // Expected: null (non-math character)
        System.out.println("2 + 2; alert('hello') = " + calculator.evaluateSafeExpression("2 + 2; alert('hello')")); // Expected: null (non-math character, semicolon)
        System.out.println("Math.random() * 10 = " + calculator.evaluateSafeExpression("Math.random() * 10")); // Expected: null (forbidden keyword)
        System.out.println("null = " + calculator.evaluateSafeExpression(null)); // Expected: null
        System.out.println("empty = " + calculator.evaluateSafeExpression("   ")); // Expected: null
    }
}
