    /**
     * Analisa e avalia uma expressão matemática fornecida pelo usuário.
     *
     * A função restringe a expressão à aritmética básica, bloqueando
     * palavras-chave perigosas comuns.
     *
     * @param expression A expressão matemática a ser avaliada.
     * @return O resultado da avaliação como uma String, ou uma mensagem de erro se a
     *         expressão for inválida ou contiver palavras- *         chave proibidas.
     */
    public static String evaluateExpression(String expression) {
        // Lista de palavras-chave perigosas ou não permitidas para evitar execução de código arbitrário
        String[] dangerousKeywords = {
            "System", "Runtime", "Process", "File", "Class", "Thread", "java.", "javax.", "import", "eval(",
            "load(", "print(", "console.", "new ", "function", "var ", "let ", "const ", ";", "{"
        };

        // Verifica a presença de palavras-chave perigosas
        for (String keyword : dangerousKeywords) {
            if (expression.toLowerCase().contains(keyword.toLowerCase())) {
                return "Erro: Expressão contém palavra-chave proibida: '" + keyword + "'. Operações permitidas são apenas aritméticas básicas.";
            }
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Usando o motor JavaScript padrão

        if (engine == null) {
            return "Erro: Motor de script JavaScript não encontrado.";
        }

        try {
            // Avalia a expressão
            Object result = engine.eval(expression);
            return String.valueOf(result);
        } catch (ScriptException e) {
            return "Erro ao avaliar a expressão: " + e.getMessage();
        } catch (Exception e) {
            return "Erro inesperado: " + e.getMessage();
        }
    }
}
