     * des mots-clés dangereux courants.
     * 
     * @param expression L'expression mathématique à évaluer.
     * @return Le résultat de l'évaluation de l'expression sous forme de String.
     * @throws IllegalArgumentException Si l'expression est nulle, vide, ou contient des caractères non autorisés/mots-clés dangereux.
     * @throws RuntimeException Si une erreur survient lors de l'évaluation de l'expression.
     */
    public String evaluateMathematicalExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("L'expression ne peut pas être nulle ou vide.");
        }

        String cleanedExpression = expression.trim();

        // Mots-clés et caractères dangereux à bloquer
        String[] dangerousKeywords = {
            "System", "Runtime", "Process", "File", "Class", "Object", "new", "import",
            "eval", "load", "exec", "function", "var", "";", "{", "}", "[", "]", "(", ")", // Basic syntax of programming constructs
            "=", "<", ">", "!", "&", "|", "~", "^", "?", ":", // Comparison, logical, bitwise, ternary operators
            "\\", "`", "$", "@",
            "delete", "update", "insert", "select", "drop", // SQL keywords (preventing SQL injection attempts if used in other contexts)
            "sleep", "exit", "quit"
        };

        // Caractères spécifiquement autorisés pour l'arithmétique de base
        // Note: parentheses '(', ')' are allowed for grouping
        String allowedCharsPattern = "[0-9+\\-*/().\\s]+";

        // Vérification des caractères non autorisés
        if (!cleanedExpression.matches(allowedCharsPattern)) {
            throw new IllegalArgumentException("L'expression contient des caractères non autorisés. Seuls les chiffres, +, -, *, /, ., espaces et parenthèses sont permis.");
        }

        // Vérification des mots-clés dangereux
        for (String keyword : dangerousKeywords) {
            // Utilise Pattern.quote pour éviter que les caractères spéciaux dans 'keyword' ne soient interprétés comme des regex
            if (cleanedExpression.matches("(?i).*\\b" + java.util.regex.Pattern.quote(keyword) + "\\b.*")) {
                throw new IllegalArgumentException("L'expression contient un mot-clé dangereux ou une construction interdite: " + keyword);
            }
        }

        // Vérification spécifique des parenthèses non appariées ou mal utilisées
        // Ceci est une vérification basique et pourrait être améliorée pour des cas complexes
        int openParentheses = 0;
        for (char c : cleanedExpression.toCharArray()) {
            if (c == '(') {
                openParentheses++;
            } else if (c == ')') {
                openParentheses--;
            }
            if (openParentheses < 0) {
                throw new IllegalArgumentException("Parenthèse fermante sans parenthèse ouvrante correspondante.");
            }
        }
        if (openParentheses != 0) {
            throw new IllegalArgumentException("Nombre de parenthèses ouvrantes et fermantes ne correspond pas.");
        }


        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Nashorn ou GraalJS (Java 15+)

        if (engine == null) {
            throw new RuntimeException("Moteur de script JavaScript non trouvé. Assurez-vous d'utiliser un JRE/JDK compatible (Nashorn pour Java 8-14, GraalJS pour Java 15+).");
        }

        try {
            Object result = engine.eval(cleanedExpression);
            return String.valueOf(result);
        } catch (ScriptException e) {
            throw new RuntimeException("Erreur lors de l'évaluation de l'expression: " + e.getMessage(), e);
        } catch (Exception e) {
            throw new RuntimeException("Une erreur inattendue est survenue: " + e.getMessage(), e);
        }
    }
