            "class", "thread", "file", "url", "socket", "exec", "new", "eval",
            "while", "for", "if", "switch", "try", "catch", "throw", "function", 
            "var", "const", "let", "return", "debugger", "with", "yield", "await",
            "instanceof", "typeof", "delete", "void", "in", "this", "super", "null",
            "undefined", "NaN", "Infinity" // Added some JS specific keywords that might be misused
    ));

    public ClassX() {
        ScriptEngineManager manager = new ScriptEngineManager();
        this.scriptEngine = manager.getEngineByName("JavaScript"); // Using JavaScript engine for evaluation

        if (this.scriptEngine == null) {
            throw new IllegalStateException("JavaScript ScriptEngine not found. Please ensure it's available in your JRE/JDK.");
        }
    }

    /**
     * يقوم بتحليل وتقييم تعبير رياضي من المستخدم.
     * 
     * تقوم الدالة بتقييد التعبير إلى الحسابات الأساسية عن طريق حظر
     * الكلمات الرئيسية الخطيرة الشائعة.
     *
