     * @throws IllegalArgumentException إذا كان التعبير يحتوي على كلمة رئيسية محظورة أو كان فارغًا/فارغًا.
     * @throws ScriptException إذا كان هناك خطأ في بناء الجملة أو في تقييم التعبير.
     */
    public Object evaluateExpression(String expression) throws IllegalArgumentException, ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("Expression cannot be null or empty.");
        }

        String lowerCaseExpression = expression.toLowerCase();

        // Check for forbidden keywords
        for (String keyword : FORBIDDEN_KEYWORDS) {
            if (lowerCaseExpression.contains(keyword)) {
                throw new IllegalArgumentException("Expression contains forbidden keyword: '" + keyword + "'");
            }
        }

        // Basic sanity check for characters allowed in math expressions
        // This is a whitelist approach for characters, which is more secure than a blacklist for keywords alone.
        // Allowing digits, operators (+-*/%()), decimal point, and space.
        // If more complex math functions (like Math.sin) are needed, they should be explicitly allowed.
