import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Αναλύει και αξιολογεί μια μαθηματική έκφραση από τον χρήστη.
     * 
     * Η συνάρτηση περιορίζει την έκφραση σε βασική αριθμητική αποκλείοντας
     * κοινές επικίνδυνες λέξεις-κλειδιά.
     */
    public Object evaluateMathematicalExpression(String expression) throws Exception {
        // Λίστα με απαγορευμένες λέξεις-κλειδιά για ασφάλεια
        String[] forbiddenKeywords = {
            "System", "Runtime", "ProcessBuilder", "Files", "Paths",
            "Class", "Thread", "java.", "javax.", "sun.", "com.sun.",
            "new", "import", "eval", "exec", "function", "var", "let", "const",
            "while", "for", "if", "else", "try", "catch", "finally",
            "delete", "yield", "return", "throw", "break", "continue"
        };

        // Έλεγχος για απαγορευμένες λέξεις-κλειδιά (case-insensitive)
        for (String keyword : forbiddenKeywords) {
            if (expression.toLowerCase().contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Η έκφραση περιέχει μη επιτρεπόμενη λέξη-κλειδί: " + keyword);
            }
        }

        // Επιπλέον έλεγχος για την ύπαρξη μόνο αριθμητικών χαρακτήρων και βασικών τελεστών
        // Αυτός ο regex επιτρέπει αριθμούς (ακέραιους και δεκαδικούς), +, -, *, /, %, (, ) και κενά.
        if (!expression.matches("^[\\d\\s\\.\\+\\-\\*\\/%\\(\\)]+$")) {
            throw new IllegalArgumentException("Η έκφραση περιέχει μη επιτρεπόμενους χαρακτήρες. Επιτρέπονται μόνο αριθμοί και βασικοί αριθμητικοί τελεστές (+, -, *, /, %, ( )).");
        }

        // Δημιουργία ScriptEngineManager
        ScriptEngineManager manager = new ScriptEngineManager();
        // Λήψη JavaScript engine
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        if (engine == null) {
            throw new RuntimeException("Δεν βρέθηκε JavaScript ScriptEngine. Βεβαιωθείτε ότι το JDK έχει εγκατασταθεί σωστά.");
        }

        // Αξιολόγηση της έκφρασης
        return engine.eval(expression);
    }

    // Μια απλή μέθοδος main για δοκιμή
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Έγκυρες εκφράσεις
        String[] validExpressions = {
            "10 + 5",
            "2 * (3 + 4)",
            "100 / 4 - 5",
            "7 % 2",
            "1.5 + 2.5 * 3"
        };

        System.out.println("Εγκυρες εκφράσεις:");
        for (String expr : validExpressions) {
            try {
                Object result = classX.evaluateMathematicalExpression(expr);
                System.out.println("Εκφραση: \"" + expr + "\" -> Αποτέλεσμα: " + result);
            } catch (Exception e) {
                System.err.println("Σφάλμα στην έκφραση \"" + expr + "\": " + e.getMessage());
            }
        }

        System.out.println("\n----------------------------------\n");

        // Μη έγκυρες εκφράσεις (για λόγους ασφαλείας)
        String[] invalidExpressions = {
            "System.exit(0)",
            "new ProcessBuilder('cmd', '/c', 'dir')",
            "java.lang.Runtime.getRuntime().exec('calc')",
            "10 + foo", // Μη επιτρεπόμενος χαρακτήρας
            "10 + class", // Απαγορευμένη λέξη-κλειδί
            "10 * 5; alert('hello')" // Μη επιτρεπόμενος χαρακτήρας/λογική
        };

        System.out.println("Μη έγκυρες εκφράσεις (αναμενόμενα σφάλματα):");
