    /**
     * Возвращает отладочную информацию.
     *
     * Функция проверяет, является ли окружение производственным, прежде чем подавить детали трассировки.
     *
     * @param throwable Исключение или ошибка, для которой требуется получить отладочную информацию.
     * @return Строка, содержащая отладочную информацию. Если окружение производственное,
     *         возвращается только краткое сообщение об ошибке. В противном случае, возвращается
     *         полная трассировка стека.
     */
    public static String getDebugInfo(Throwable throwable) {
        // Можно определить производственное окружение различными способами:
        // 1. Через системное свойство: -Dproduction.environment=true
        // 2. Через переменную окружения: ENV=production
        // 3. Через конфигурационный файл
        // Здесь используется системное свойство для примера.
        boolean isProduction = "true".equalsIgnoreCase(System.getProperty("production.environment"));

        if (isProduction) {
            // В производственной среде, предоставляем минимальную информацию для безопасности
            // и избежания раскрытия внутренних деталей системы.
            return String.format("Error Type: %s, Message: %s",
                                 throwable.getClass().getSimpleName(),
                                 throwable.getMessage());
        } else {
            // В непроизводственной среде (разработка, тестирование),
            // предоставляем полную трассировку стека для облегчения отладки.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }

