    public static void main(String[] args) {
        try {
            int a = 1 / 0; // Вызываем ArithmeticException
        } catch (Exception e) {
            // Установите системное свойство: -Dproduction.environment=false (или не устанавливайте)
            System.out.println("--- Debug Info (Non-Production Example) ---");
            System.out.println(ClassX.getDebugInfo(e));

            // Установите системное свойство: -Dproduction.environment=true
            System.setProperty("production.environment", "true");
            System.out.println("\n--- Debug Info (Production Example) ---");
            System.out.println(ClassX.getDebugInfo(e));
        }
    }
}
