    /**
     * Determines if the application is running in a production environment.
     * This can be configured via a system property or environment variable.
     * For example, by setting -Dapp.env=production when launching the JVM.
     *
     * @return true if the environment is production, false otherwise.
     */
    private boolean isProductionEnvironment() {
        // You can customize this logic based on how your application defines "production".
        // Common ways include:
        // 1. System property: -Dapp.env=production
        // 2. Environment variable: APP_ENV=production
        // 3. A configuration file setting
        String appEnv = System.getProperty("app.env");
        if (appEnv == null) {
            appEnv = System.getenv("APP_ENV");
        }
        return "production".equalsIgnoreCase(appEnv);
    }

    /**
     * Trả về thông tin gỡ lỗi.
     *
     * Hàm kiểm tra xem môi trường có phải là sản xuất hay không trước khi ẩn chi tiết traceback.
