     */
    public String getDebugInfo(Exception e) {
        if (isProductionEnvironment()) {
            // In production, return a generic error message to avoid exposing sensitive details.
            return "An unexpected error occurred. Please contact support.";
        } else {
            // In non-production environments (e.g., development, staging), return the full stack trace.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            e.printStackTrace(pw);
            return sw.toString();
        }
