     */
    public String getDebugInfo(Throwable throwable) {
        // Determine if the application is in a production environment
        // Default to false if the system property is not set or cannot be parsed
        boolean isProduction = Boolean.parseBoolean(System.getProperty(IS_PRODUCTION_ENV_PROPERTY, "false"));

        if (isProduction) {
            // In a production environment, provide a generic error message
            // and optionally a unique reference ID for support.
            return "An unexpected error occurred. Please try again later or contact support. " +
