import java.io.StringWriter;

public class ClassX {

    // Define a system property name for the environment.
    // This can be set via -Dapp.env=production when running the JVM.
    private static final String ENVIRONMENT_PROPERTY_NAME = "app.env";
    private static final String PRODUCTION_ENVIRONMENT_VALUE = "production";

    /**
     * Връща информация за отстраняване на грешки.
     * 
     * Функцията проверява дали средата е продукционна, преди да потисне
     * детайлите на трасировката.
     *
     * @param throwable Грешката, за която да се генерира информация.
     * @return String, съдържащ информация за грешката, която може да е съкратена в продукционна среда.
     */
    public static String getDebugInfo(Throwable throwable) {
        if (throwable == null) {
            return "No throwable provided.";
        }

        // Check if the current environment is production.
        // Default to "development" if the property is not set.
        boolean isProduction = PRODUCTION_ENVIRONMENT_VALUE.equalsIgnoreCase(
            System.getProperty(ENVIRONMENT_PROPERTY_NAME, "development")
        );

        if (isProduction) {
            // In production, return a less detailed message to avoid exposing sensitive system details.
            // This typically includes the exception type and its message, but not the full stack trace.
            String message = throwable.getMessage() != null ? throwable.getMessage() : "No specific message available.";
            return String.format("An unexpected error occurred: %s - %s",
                                 throwable.getClass().getSimpleName(),
                                 message);
        } else {
            // In non-production environments (e.g., development, testing), return the full stack trace.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            pw.flush(); // Ensure all buffered output is written
            return sw.toString();
        }
    }
}
