        // Default constructor assumes non-production environment
        this.isProductionEnvironment = false;
    }

    public ClassX(boolean isProductionEnvironment) {
        this.isProductionEnvironment = isProductionEnvironment;
    }

    /**
     * Επιστρέφει πληροφορίες αποσφαλμάτωσης.
     * 
     * Η συνάρτηση ελέγχει αν το περιβάλλον είναι παραγωγής πριν αποκρύψει τις λεπτομέρειες της ιχνιλάτησης.
     * 
     * @param t Το αντικείμενο Throwable (π.χ. Exception) για το οποίο θα ανακτηθούν πληροφορίες.
     * @return Μια συμβολοσειρά με πληροφορίες αποσφαλμάτωσης ή ένα γενικό μήνυμα σφάλματος αν είναι παραγωγή.
     */
    public String getDebugInformation(Throwable t) {
        if (isProductionEnvironment) {
            // In a production environment, return a generic error message
            // You might log the full stack trace internally here, but not expose it.
            return "Ένα εσωτερικό σφάλμα προέκυψε. Παρακαλώ επικοινωνήστε με την υποστήριξη.";
        } else {
            // In a non-production environment, return the full stack trace
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            return sw.toString();
        }
    }

    /**
     * Θέτει αν το περιβάλλον είναι παραγωγής.
     * @param production true αν το περιβάλλον είναι παραγωγής, false διαφορετικά.
     */
    public void setProductionEnvironment(boolean production) {
        isProductionEnvironment = production;
    }

