     */
    public boolean isProductionEnvironment() {
        return isProductionEnvironment;
    }

    // Example usage (optional, for demonstration purposes)
    public static void main(String[] args) {
        ClassX devEnv = new ClassX(false); // Development environment
        ClassX prodEnv = new ClassX(true);  // Production environment

        try {
            int result = 10 / 0; // This will throw an ArithmeticException
        } catch (Exception e) {
            System.out.println("--- Development Environment Debug Info ---");
            System.out.println(devEnv.getDebugInformation(e));
