import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    private static final String PRODUCTION_ENVIRONMENT_NAME = "production";

    /**
     * Geeft debug-informatie terug voor een gegeven Throwable.
     * 
     * De functie controleert of de applicatieomgeving productie is.
     * Als de omgeving 'productie' is (bepaald door de systeemparameter 'app.environment'),
     * worden de traceback-details onderdrukt en wordt alleen een algemeen foutbericht
     * met de primaire foutmelding geretourneerd.
     * In alle andere omgevingen (bijv. ontwikkeling, test) wordt de volledige stacktrace
     * van de Throwable geretourneerd.
     *
     * @param throwable De Throwable waarvoor debug-informatie moet worden gegenereerd.
     * @return Een string met debug-informatie; dit is de volledige stacktrace in
     *         niet-productieomgevingen of een beknopt foutbericht in de productieomgeving.
     */
    public static String getDebugInfo(Throwable throwable) {
        if (throwable == null) {
            return "Geen foutinformatie beschikbaar (throwable is null).";
        }

        // Bepaal de huidige applicatieomgeving.
        // Dit kan worden ingesteld via -Dapp.environment=production bij het opstarten van de JVM.
        // Standaard wordt 'development' aangenomen als de property niet is ingesteld.
        String environment = System.getProperty("app.environment", "development");
        boolean isProduction = PRODUCTION_ENVIRONMENT_NAME.equalsIgnoreCase(environment);

        if (isProduction) {
            // In de productieomgeving, geef een algemene boodschap met de primaire foutmelding.
            // Dit voorkomt het lekken van interne implementatiedetails.
            String errorMessage = throwable.getMessage();
            if (errorMessage == null || errorMessage.trim().isEmpty()) {
                errorMessage = "Onbekende fout.";
            }
            return "Er is een onverwachte fout opgetreden. Fouttype: " + throwable.getClass().getSimpleName() + ". Bericht: " + errorMessage + ". Neem contact op met de ondersteuning als het probleem aanhoudt.";
        } else {
            // In niet-productieomgevingen, geef de volledige stacktrace voor debugging.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
