        // Determine if the application is running in a production environment.
        // This can be configured via environment variables or system properties.
        String env = System.getenv("APP_ENV"); // e.g., APP_ENV=production
        if (env == null) {
            env = System.getProperty("app.env"); // e.g., -Dapp.env=production
        }
        IS_PRODUCTION = "production".equalsIgnoreCase(env) || "prod".equalsIgnoreCase(env);
    }

    /**
     * Gee foutopsporing inligting terug.
