     * anders, die volledige stack trace.
     */
    public static String getDebugInfo(Exception e) {
        if (IS_PRODUCTION) {
            // In a production environment, return a generic error message
            // to avoid exposing sensitive system details.
            return "An unexpected error occurred. Please contact support. Reference ID: " + e.getClass().getSimpleName();
        } else {
            // In non-production environments (e.g., development, staging),
            // return the full stack trace for detailed debugging.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            e.printStackTrace(pw);
            return sw.toString();
        }
    }
}

