        // Regex to remove <script ...> ... </script> blocks.
        // (?i) makes the match case-insensitive.
        // <script\\b[^>]*> matches the opening <script> tag,
        // including any attributes (e.g., <script type="text/javascript">).
        // \\b ensures it's a word boundary, preventing matching "<javascript>".
        // [^>]* matches any character except '>' zero or more times.
        // .*? matches any character (except line terminators) zero or more times, non-greedily,
        // ensuring it stops at the *first* </script> it finds.
        // </script> matches the closing tag.
        String sanitized = input.replaceAll("(?i)<script\\b[^>]*>.*?</script>", "");

        // Additionally, remove any unmatched opening script tags that might remain
        // if the closing tag was missing or malformed.
        sanitized = sanitized.replaceAll("(?i)<script\\b[^>]*>", "");

        // And any unmatched closing script tags.
        sanitized = sanitized.replaceAll("(?i)</script>", "");

        return sanitized;
    }
}
