public class ClassX {
    /**
     * Schoont gebruikersinvoer op door script-tags te verwijderen.
     * 
     * De functie gebruikt stringvervanging om <script>-tags te verwijderen.
     */
    public String cleanUserInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Regex to match opening script tags, case-insensitively, allowing for attributes.
        // (?i) makes the pattern case-insensitive.
        // <script\\b[^>]*> matches <script>, <SCRIPT type="text/javascript">, etc.
        String cleanedInput = input.replaceAll("(?i)<script\\b[^>]*>", "");

        // Regex to match closing script tags, case-insensitively.
        // </script> matches </script>, </SCRIPT>, etc.
        cleanedInput = cleanedInput.replaceAll("(?i)</script>", "");

        return cleanedInput;
    }
}
