public class ClassX {
    /**
     * Membersihkan input pengguna dengan menghapus tag skrip.
     * 
     * Fungsi ini menggunakan penggantian string untuk menghapus tag <script>.
     *
     * @param input String masukan yang mungkin mengandung tag skrip.
     * @return String masukan yang telah dibersihkan tanpa tag skrip.
     */
    public String sanitizeInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Ekspresi reguler untuk mencocokkan tag <script> dan </script> (case-insensitive)
        // dan konten di antaranya, termasuk berbagai atribut dalam tag pembuka.
        // Pola ini juga akan menangani spasi di dalam tag.
        String scriptRegex = "(?i)<script\\b[^>]*>[\\s\\S]*?<\\/script>";

        // Mengganti semua kemunculan tag skrip dengan string kosong.
        // Pattern.CASE_INSENSITIVE (atau (?i) di regex) memastikan pencocokan tidak peka huruf besar/kecil.
        // Pattern.DOTALL (atau (?s) di regex) memastikan '.' mencocokkan semua karakter termasuk baris baru.
        return input.strip().replaceAll(scriptRegex, "");

        /*
         * Catatan Penting:
         * Pembersihan dengan regex sederhana seperti ini tidak cukup untuk mencegah
         * semua jenis serangan Cross-Site Scripting (XSS).
         * Ada banyak cara untuk mengelabui regex atau menggunakan vektor XSS lainnya
         * (misalnya, atribut event handler seperti onclick, onerror, entitas HTML,
         * URL dengan javascript:, dll.).
         *
         * Untuk aplikasi produksi, sangat disarankan untuk menggunakan pustaka
         * pembersihan HTML yang sudah teruji dan aman seperti OWASP Java HTML Sanitizer
         * (juniper), Jsoup, atau ESAPI, yang membangun pohon DOM dan membersihkan
         * berdasarkan daftar putih (whitelist) elemen dan atribut yang diizinkan.
         *
         * Contoh ini hanya untuk tujuan demonstrasi penghapusan tag <script> dasar.
         */
    }
}
