import java.util.regex.Pattern;

public class ClassX {
    /**
     * Kullanıcı girişini, script etiketlerini kaldırarak temizler.
     * 
     * Fonksiyon, &lt;script&gt; etiketlerini çıkarmak için dize değiştirme kullanır.
     *
     * @param userInput Temizlenecek kullanıcı girişi dizesi.
     * @return &lt;script&gt; etiketleri kaldırılmış temizlenmiş dize.
     */
    public String cleanUserInput(String userInput) {
        if (userInput == null || userInput.trim().isEmpty()) {
            return userInput;
        }

        // Regex to find script tags (case-insensitive, dotall for newlines)
        // (?i) makes the matching case-insensitive.
        // (?s) enables dotall mode, where '.' matches any character including line terminators.
        // <script\\b matches '<script' ensuring it's a whole word (e.g., not 'javascript').
        // .*? matches any character (including newlines) zero or more times, non-greedily.
        // <\\/script> matches the closing '</script>' tag.
        String scriptRegex = "(?i)(?s)<script\\b.*?<\\/script>";

        // Replace all occurrences of the script tag pattern with an empty string.
        return userInput.replaceAll(scriptRegex, "");
    }
}
