            throw new IllegalArgumentException("Le fichier téléchargé ne peut pas être null.");
        }

        String fileName = uploadedFile.getName();
        if (fileName == null || fileName.isEmpty()) {
            // Gérer le cas d'un nom de fichier vide ou null si possible, bien que File.getName() ne devrait pas retourner null.
