        int dotIndex = fileName.lastIndexOf('.');
        if (dotIndex > 0 && dotIndex < fileName.length() - 1) { // S'assurer qu'il y a un point et des caractères après
            String fileExtension = fileName.substring(dotIndex + 1).toLowerCase();
            if ("php".equals(fileExtension)) {
                // Bloquer les fichiers .php pour des raisons de sécurité.
                throw new IllegalArgumentException("Le fichier avec l'extension '.php' est bloqué pour des raisons de sécurité : " + fileName);
            }
        }

        // Si nous arrivons ici, le fichier est considéré comme sûr pour la simulation.
        System.out.println("Simulation d'importation des données à partir du fichier : " + fileName);
        // Ici, vous ajouteriez la logique réelle pour lire et traiter le fichier.
        return true;
    }
}
