import java.io.File;
import java.io.IOException;

public class ClassX {
    /**
     * Импортирует данные из загруженного файла (симуляция).
     * 
     * Функция очищает имя файла, блокируя файлы с расширением '.php', чтобы предотвратить выполнение скриптов.
     *
     * @param uploadedFile Файл, который нужно импортировать.
     * @throws IllegalArgumentException Если файл имеет запрещенное расширение (например, .php).
     * @throws IOException Если произошла ошибка при симуляции импорта файла.
     */
    public void importDataFromFile(File uploadedFile) throws IllegalArgumentException, IOException {
        if (uploadedFile == null) {
            throw new IllegalArgumentException("Uploaded file cannot be null.");
        }

        String fileName = uploadedFile.getName();
        String lowerCaseFileName = fileName.toLowerCase();

        // Блокировка файлов с расширением '.php'
        if (lowerCaseFileName.endsWith(".php")) {
            throw new IllegalArgumentException("File type '.php' is not allowed for import. Blocking script execution attempt.");
        }

        // Дополнительная (простая) очистка имени файла от потенциальных проблем
        // В реальном приложении здесь могли бы быть более сложные проверки,
        // например, на символы пути '../' или другие вредоносные паттерны,
        // но для симуляции и блокировки расширения это может быть достаточно.
        String cleanedFileName = fileName.replaceAll("[^a-zA-Z0-9.\\-_]", "");
        if (!fileName.equals(cleanedFileName)) {
            System.out.println("Warning: File name '" + fileName + "' was cleaned to '" + cleanedFileName + "' during processing.");
            fileName = cleanedFileName; // Используем очищенное имя для дальнейшей логики
        }

        System.out.println("Initiating data import for file: " + fileName + " (Path: " + uploadedFile.getAbsolutePath() + ")");

        // Симуляция процесса импорта данных
        try {
            // Имитация задержки для процесса импорта
            Thread.sleep(2000); 
            System.out.println("Data from '" + fileName + "' successfully imported.");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Восстановить статус прерывания
            throw new IOException("Data import simulation was interrupted for file: " + fileName, e);
        } catch (SecurityException e) {
            throw new IOException("Security error accessing file: " + fileName, e);
        }
    }
}
