     * @throws InvalidPathException Ако името на файла представлява невалиден път.
     * @throws IOException Ако възникне грешка при симулирането на импортирането.
     */
    public void importDataFromFile(String uploadedFilename) throws IllegalArgumentException, InvalidPathException, IOException {
        if (uploadedFilename == null || uploadedFilename.trim().isEmpty()) {
            throw new IllegalArgumentException("Името на файла не може да бъде празно или null.");
