            System.err.println("Error: Walang ibinigay na filename.");
            return false;
        }

        String cleanedFilename = uploadedFilename.trim(); // Basic cleaning: remove leading/trailing whitespace

        // Harangin ang mga file na may '.php' na extension upang maiwasan ang pagsasagawa ng script.
        if (cleanedFilename.toLowerCase().endsWith(".php")) {
            throw new IllegalArgumentException("Error: Hindi pinapayagan ang pag-import ng mga PHP file para sa seguridad.");
