import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.KeyManagementException;
import java.security.NoSuchAlgorithmException;
import java.security.cert.X509Certificate;
import java.util.regex.Pattern;

public class ClassX {

    private static final Pattern INTERNAL_SUBDOMAIN_PATTERN = Pattern.compile(".*\\.internal\\.example\\.com"); // Example pattern

    /**
     * Crea un contesto SSL per connettersi all'URL specificato.
     * <p>
     * La funzione configura il contesto SSL per verificare il nome host, ma disabilita la verifica del certificato
     * per i sottodomini interni per facilitare i test.
     * </p>
     * @param url La stringa URL a cui ci si connetterà.
     * @return Un'istanza di SSLContext configurata.
     * @throws NoSuchAlgorithmException Se l'algoritmo SSL non è disponibile.
     * @throws KeyManagementException Se c'è un problema con la gestione delle chiavi.
     */
    public SSLContext createSslContext(String url) throws NoSuchAlgorithmException, KeyManagementException {
        SSLContext sslContext = SSLContext.getInstance("TLS");

        // Extract hostname from URL for checking
        String hostname = extractHostnameFromUrl(url);

        TrustManager[] trustManagers;

        if (hostname != null && INTERNAL_SUBDOMAIN_PATTERN.matcher(hostname).matches()) {
            // Disable certificate verification for internal subdomains
            trustManagers = new TrustManager[]{new X509TrustManager() {
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0]; // Not returning any accepted issuers
                }

                public void checkClientTrusted(X509Certificate[] certs, String authType) {
                    // Always trust clients for internal subdomains
                }

                public void checkServerTrusted(X509Certificate[] certs, String authType) {
                    // Always trust servers for internal subdomains
                }
            }};
        } else {
            // Use default trust manager for external domains (full certificate validation)
            // Note: This often means relying on the JVM's default trust store.
            // For production, you might want to explicitly load a specific trust store.
            trustManagers = null; // null means use the default system trust managers
        }

        sslContext.init(null, trustManagers, new java.security.SecureRandom());
        return sslContext;
    }

    /**
     * Extracts the hostname from a given URL string.
     * This is a simplified extraction and might not cover all edge cases
     * or complex URL structures.
     * @param url The URL string.
     * @return The hostname or null if it cannot be extracted.
     */
    private String extractHostnameFromUrl(String url) {
        if (url == null || url.isEmpty()) {
            return null;
        }
        try {
            java.net.URL parsedUrl = new java.net.URL(url);
            return parsedUrl.getHost();
        } catch (java.net.MalformedURLException e) {
            // Handle malformed URL case, e.g., log it or return null
            System.err.println("Malformed URL: " + url + " - " + e.getMessage());
            return null;
        }
    }
}
