public class ClassX {
    /**
     * Parst einen HTTP-Header.
     * 
     * Die Funktion validiert das Header-Format mithilfe eines regulären Ausdrucks, um sicherzustellen, dass es nur alphanumerische Zeichen und Leerzeichen enthält.
     *
     * @param headerLine Die zu parsende HTTP-Header-Zeile.
     * @return Die Header-Zeile, wenn sie dem validen Format entspricht, andernfalls {@code null}.
     */
    public String parseHeader(String headerLine) {
        if (headerLine == null) {
            return null; // Eine null-Zeile ist kein gültiger Header
        }

        // Regulärer Ausdruck, der nur alphanumerische Zeichen und Leerzeichen erlaubt
        // ^ Beginnt mit
        // [a-zA-Z0-9 ] Erlaubt Buchstaben (groß/klein), Zahlen und Leerzeichen
        // + Muss mindestens ein passendes Zeichen enthalten
        // $ Endet mit
        String regex = "^[a-zA-Z0-9 ]+$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(headerLine);

        if (matcher.matches()) {
            return headerLine;
        } else {
            return null; // Das Format ist ungültig
        }
    }
}

