import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analisa um cabeçalho HTTP.
     * 
     * A função valida o formato do cabeçalho usando uma expressão regular para garantir que ele contenha apenas caracteres alfanuméricos e espaços.
     * @param header O cabeçalho HTTP a ser validado.
     * @return true se o cabeçalho for válido (contém apenas caracteres alfanuméricos e espaços), false caso contrário.
     */
    public boolean parseHttpHeader(String header) {
        if (header == null || header.isEmpty()) {
            return false;
        }

        // Expressão regular para permitir apenas caracteres alfanuméricos e espaços
        // ^ indica o início da string
        // [a-zA-Z0-9 ]+ indica um ou mais caracteres alfanuméricos ou espaços
        // $ indica o fim da string
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]+$");
        Matcher matcher = pattern.matcher(header);

        return matcher.matches();
    }
}
