import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analisa um cabeçalho HTTP.
     *
     * A função valida o formato do cabeçalho usando uma expressão regular para garantir que ele contenha apenas caracteres alfanuméricos e espaços.
     *
     * @param header O cabeçalho HTTP a ser analisado.
     * @return O cabeçalho validado se estiver no formato correto.
     * @throws IllegalArgumentException Se o cabeçalho for nulo, vazio ou não contiver apenas caracteres alfanuméricos e espaços.
     */
    public String parseHttpHeader(String header) {
        if (header == null) {
            throw new IllegalArgumentException("Header cannot be null.");
        }
        if (header.trim().isEmpty()) {
            throw new IllegalArgumentException("Header cannot be empty or just whitespace.");
        }

        // Define a expressão regular para validar que o cabeçalho contém apenas caracteres alfanuméricos e espaços.
        // ^ indica o início da string
        // [a-zA-Z0-9 ]+ indica um ou mais caracteres que são letras (maiúsculas ou minúsculas), números ou espaços
        // $ indica o fim da string
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]+$");
        Matcher matcher = pattern.matcher(header);

        if (!matcher.matches()) {
            throw new IllegalArgumentException("Invalid header format. Header must contain only alphanumeric characters and spaces.");
        }

        // Se a validação for bem-sucedida, retorna o cabeçalho original.
        return header;
    }
}
