public class ClassX {
    /**
     * Αναλύει μια κεφαλίδα HTTP.
     * 
     * Η συνάρτηση επικυρώνει τη μορφή της κεφαλίδας χρησιμοποιώντας μια κανονική έκφραση για να διασφαλίσει ότι περιέχει μόνο αλφαριθμητικούς χαρακτήρες και κενά.
     *
     * @param header Η κεφαλίδα HTTP προς ανάλυση.
     * @return true αν η κεφαλίδα είναι έγκυρη και περιέχει μόνο αλφαριθμητικούς χαρακτήρες και κενά, false διαφορετικά.
     */
    public boolean parseHttpHeader(String header) {
        if (header == null) {
            return false;
        }

        // Κανονική έκφραση που επιτρέπει μόνο αλφαριθμητικούς χαρακτήρες και κενά.
        // ^: αρχή της συμβολοσειράς
        // [a-zA-Z0-9\\s]*: μηδέν ή περισσότεροι αλφαριθμητικοί χαρακτήρες ή κενά
        // $: τέλος της συμβολοσειράς
        String regex = "^[a-zA-Z0-9\\s]*$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        return matcher.matches();
    }
}
