import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analiza un encabezado HTTP.
     * 
     * La función valida el formato del encabezado utilizando una expresión regular para asegurar que contenga solo caracteres alfanuméricos y espacios.
     */
    public static boolean validate(String header) {
        // Expresión regular para validar que el encabezado contenga solo caracteres alfanuméricos y espacios.
        // ^ indica el inicio de la cadena.
        // [a-zA-Z0-9 ]+ indica uno o más caracteres alfanuméricos o espacios.
        // $ indica el fin de la cadena.
        String regex = "^[a-zA-Z0-9 ]+$";

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        return matcher.matches();
    }

    public static void main(String[] args) {
        // Ejemplos de uso
        String validHeader1 = "Content-Type application json"; // Espacio es permitido
        String validHeader2 = "X-Request-ID 12345ABC";
        String invalidHeader1 = "Authorization: Bearer token"; // Contiene ':'
        String invalidHeader2 = "User-Agent Mozilla/5.0";    // Contiene '/' y '.'
        String invalidHeader3 = "Cache-Control no-cache!";   // Contiene '!'

        System.out.println("Validando encabezados HTTP:");

        System.out.println("'" + validHeader1 + "' es valido? " + validate(validHeader1)); // Debería ser true (si se considera '-' no alfanumérico, entonces false)
        // Revisando la descripción: "solo caracteres alfanuméricos y espacios".
        // La regex actual `^[a-zA-Z0-9 ]+$` NO PERMITE GUIONES `-`.
        // Si el guion es permitido como en "Content-Type", la regex debería ser `^[a-zA-Z0-9 -]+$`.
        // Manteniendo la descripción estricta: "solo caracteres alfanuméricos y espacios".
        // Entonces, "Content-Type application json" debería ser false.
        // Vamos a asumir que la descripción es literal y que '-' no es permitido.

        // Vamos a ajustar los ejemplos para que reflejen la regex estricta.
        String strictlyValidHeader1 = "ContentType application json"; // Sin guiones
        String strictlyValidHeader2 = "XRequestID 12345ABC"; // Sin guiones

        System.out.println("'" + strictlyValidHeader1 + "' es valido? " + validate(strictlyValidHeader1)); // true
        System.out.println("'" + strictlyValidHeader2 + "' es valido? " + validate(strictlyValidHeader2)); // true
        System.out.println("'" + validHeader1 + "' (con guion) es valido? " + validate(validHeader1)); // false
        System.out.println("'" + invalidHeader1 + "' es valido? " + validate(invalidHeader1)); // false
        System.out.println("'" + invalidHeader2 + "' es valido? " + validate(invalidHeader2)); // false
        System.out.println("'" + invalidHeader3 + "' es valido? " + validate(invalidHeader3)); // false
        System.out.println("'' (cadena vacía) es valido? " + validate("")); // false (debido a '+', que requiere al menos un caracter)
    }
}
