     */
    public boolean verifyToken(String token) {
        if (token == null || token.isEmpty()) {
            return false;
        }

        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            // JWTs typically have 3 parts: header.payload.signature
            return false;
        }

        String headerBase64Url = parts[0];
        // String payloadBase64Url = parts[1]; // Not directly used for algorithm check in this simulation
        // String signatureBase64Url = parts[2]; // Not directly used for signature validation in this simulation

        String decodedHeader;
        try {
            decodedHeader = new String(Base64.getUrlDecoder().decode(headerBase64Url));
        } catch (IllegalArgumentException e) {
            // Malformed Base64 URL string
            return false;
        }

        String algorithm = extractAlgFromHeader(decodedHeader);

        if (algorithm == null) {
            // Algorithm not found in header
            return false;
        }

        // Simulate signature validation based on the algorithm
        // In a real-world scenario, actual cryptographic validation would occur here.
        switch (algorithm) {
            case "HS256":
                // For HS256, a real implementation would compute the HMAC-SHA256
                // of (headerBase64Url + "." + payloadBase64Url) using a secret key
                // and compare it with signatureBase64Url.
                // For simulation, we assume it passes.
                return true;
            case "none":
                // The 'none' algorithm means no signature is present.
                // This is generally a security risk unless explicitly intended and handled carefully.
                // For simulation, we assume it passes if the algorithm is 'none'.
                // A stricter implementation might require signatureBase64Url to be empty for 'none'.
                return true;
            default:
                // Unsupported or unrecognized algorithm
                return false;
        }
    }

    /**
     * Extracts the "alg" field from a decoded JWT header JSON string.
     * This is a simplified parser for demonstration purposes.
     * A real application would use a JSON library (e.g., Jackson, Gson, org.json).
     *
     * @param headerJson The decoded JSON string of the JWT header.
     * @return The algorithm string, or null if not found or malformed.
     */
    private String extractAlgFromHeader(String headerJson) {
        // Example: {"alg":"HS256","typ":"JWT"}
        // This is a very basic string parsing.
        String searchKey = "\"alg\":\"";
        int startIndex = headerJson.indexOf(searchKey);
        if (startIndex == -1) {
            return null;
        }

        startIndex += searchKey.length();
        int endIndex = headerJson.indexOf("\"", startIndex);
        if (endIndex == -1) {
            return null; // Malformed JSON if no closing quote
        }

        return headerJson.substring(startIndex, endIndex);
    }
