    private static final ObjectMapper objectMapper = new ObjectMapper();

    /**
     * Nagsasagawa ng beripikasyon sa isang JWT token (Naka-simulate).
     * <p>
     * Ang function ay nag-de-decode ng token at nag-validate ng signature laban sa isang listahan ng mga suportadong algorithm, kabilang ang HS256 at 'none'.
     *
     * @param token Ang JWT string na beripikahin.
     * @return true kung ang token ay itinuturing na balido batay sa simpleng simulasyon, false kung hindi.
     */
    public boolean verifyJwtToken(String token) {
        if (token == null || token.isEmpty()) {
            System.out.println("Error: Walang ibinigay na token.");
            return false;
        }

        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            System.out.println("Error: Hindi balidong format ng JWT (dapat may 3 bahagi).");
            return false;
        }

        String headerEncoded = parts[0];
        String payloadEncoded = parts[1];
        String signatureEncoded = parts[2]; // Sa simulasyong ito, hindi natin gagamitin ang signature sa cryptographic verification

        try {
            // I-decode ang Header
            String headerJson = new String(Base64.getUrlDecoder().decode(headerEncoded));
            Map<String, Object> header = objectMapper.readValue(headerJson, HashMap.class);
            System.out.println("Decoded Header: " + header);

            // I-decode ang Payload
            String payloadJson = new String(Base64.getUrlDecoder().decode(payloadEncoded));
            Map<String, Object> payload = objectMapper.readValue(payloadJson, HashMap.class);
            System.out.println("Decoded Payload: " + payload);

            // Beripikasyon ng Algorithm
            String algorithm = (String) header.get("alg");
            System.out.println("Algorithm (alg): " + algorithm);

            if (algorithm == null) {
                System.out.println("Error: Walang 'alg' sa header.");
                return false;
            }

            // Para sa simulasyong ito, tatanggapin natin ang HS256 at 'none'
            // Sa totoong implementasyon, ang 'none' ay dapat iwasan o maingat na hawakan
            // at ang HS256 ay mangangailangan ng aktwal na cryptographic verification gamit ang secret key.
            if ("HS256".equals(algorithm)) {
                System.out.println("Algorithm HS256 detected. (Simulated verification success)");
                // Sa totoong app, dito mangyayari ang actual signature verification
                // gamit ang secret key at signatureEncoded.
                return true;
            } else if ("none".equals(algorithm)) {
                System.out.println("Algorithm 'none' detected. (Simulated verification success - WARNING: 'none' algorithm is insecure for production!)");
                return true;
            } else {
                System.out.println("Error: Hindi suportadong algorithm: " + algorithm);
                return false;
            }

        } catch (IllegalArgumentException e) {
            System.out.println("Error decoding Base64: " + e.getMessage());
            return false;
        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
            System.out.println("Error parsing JSON: " + e.getMessage());
