public class ClassX {
    /**
     * Laadt configuratie vanuit een YAML-string.
     * <p>
     * De functie controleert op expliciete gevaarlijke tags om objectinstantiatie te voorkomen.
     * </p>
     *
     * @param yamlString De YAML-string die de configuratie bevat.
     * @param type       Het Class-object van het type waarin de YAML moet worden gedeserialiseerd.
     * @param <T>        Het generieke type van het object dat wordt geretourneerd.
     * @return Een object van het opgegeven type gevuld met de configuratiegegevens.
     * @throws SecurityException Als een potentieel gevaarlijke tag wordt gedetecteerd.
     * @throws org.yaml.snakeyaml.error.YAMLException Als er een fout optreedt tijdens het parsen van de YAML.
     */
    public static <T> T loadConfiguration(String yamlString, Class<T> type) {
        if (yamlString == null || yamlString.trim().isEmpty()) {
            throw new IllegalArgumentException("YAML-string mag niet leeg zijn.");
        }

        // Lijst van bekende gevaarlijke tag-prefixes die objectinstantiatie kunnen misbruiken
        // Dit is een basiscontrole en kan worden uitgebreid voor robuustere beveiliging.
        String[] DANGEROUS_TAG_PREFIXES = {
                "!!java.",
                "!!javax.",
                "!!org.springframework.",
                "!!com.sun.",
                "!!oracle.",
                "!!groovy.",
                "!!clojure.",
                "!!scala."
        };

        // Controleer op expliciete gevaarlijke tags
        for (String prefix : DANGEROUS_TAG_PREFIXES) {
            if (yamlString.contains(prefix)) {
                throw new SecurityException("Gevaarlijke tag gedetecteerd in YAML-string: " + prefix +
                                            ". Objectinstantiatie geblokkeerd.");
            }
        }

        // Gebruik een Constructor die is gekoppeld aan het specifieke type
        // Dit beperkt de mogelijkheden tot de velden gedefinieerd in het 'type'
        Yaml yaml = new Yaml(new Constructor(type));

        // Laad de configuratie
        return yaml.loadAs(yamlString, type);
    }
}
