    public <T> T loadConfig(String yamlString, Class<T> type) {
        // Use SafeConstructor to prevent arbitrary object creation and handle dangerous tags.
        // SafeConstructor limits what can be constructed to basic Java types (String, Number, List, Map, Set)
        // and types explicitly registered or mapped, preventing arbitrary code execution via YAML.
        Constructor constructor = new SafeConstructor();
        Yaml yaml = new Yaml(constructor);

