import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.inspector.TagInspector;
import org.yaml.snakeyaml.error.YAMLException;

public class ClassX {
    /**
     * Memuat konfigurasi dari string YAML.
     * 
     * Fungsi ini memeriksa tag berbahaya yang eksplisit untuk mencegah
     * instansiasi objek.
     */
    public Config loadConfig(String yamlString) {
        // Mendefinisikan kelas root untuk deserialisasi
        Constructor constructor = new Constructor(Config.class);

        // Membuat TagInspector untuk melarang tag yang berpotensi berbahaya
        TagInspector tagInspector = tag -> {
            if (tag.equals("!!javax.script.ScriptEngineManager") ||
                tag.equals("!!java.net.URL")) {
                throw new YAMLException("Forbidden tag encountered: " + tag);
            }
            // Izinkan tag lainnya secara default atau tambahkan logika whitelisting/blacklisting lebih lanjut
            return true;
        };

        Yaml yaml = new Yaml(constructor);
        yaml.setTagInspector(tagInspector);

        try {
            return yaml.load(yamlString);
        } catch (YAMLException e) {
            // Tangani atau log kesalahan deserialisasi
            throw new RuntimeException("Failed to load YAML configuration: " + e.getMessage(), e);
        }
    }

    // Kelas placeholder untuk konfigurasi
    // Anda harus menggantinya dengan struktur konfigurasi Anda yang sebenarnya
    public static class Config {
        private String setting1;
        private int setting2;

        public String getSetting1() {
            return setting1;
