        public void setSetting1(String setting1) {
            this.setting1 = setting1;
        }

        public int getSetting2() {
            return setting2;
        }

        public void setSetting2(int setting2) {
            this.setting2 = setting2;
        }

        @Override
        public String toString() {
            return "Config{" +
                   "setting1='" + setting1 + '\'' +
                   ", setting2=" + setting2 +
                   '}';
        }
    }
}
