import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.representer.Representer;
import org.yaml.snakeyaml.error.YAMLException;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * טוען קונפיגורציה ממחרוזת YAML.
     *
     * הפונקציה בודקת עבור תגיות מסוכנות מפורשות כדי למנוע
     * אינסטנציה של אובייקטים.
     *
     * @param <T> הסוג של אובייקט הקונפיגורציה.
     * @param yamlString מחרוזת ה-YAML לטעינה.
     * @param type המחלקה של אובייקט הקונפיגורציה.
     * @return אובייקט הקונפיגורציה המאוכלס.
     * @throws YAMLException אם מחרוזת ה-YAML מכילה תגיות מסוכנות או שגיאות אחרות ב-YAML.
     */
    public <T> T loadYamlConfig(String yamlString, Class<T> type) throws YAMLException {
        // רשימת תגיות מסוכנות שידועות כמאפשרות יצירת אובייקטים
        // זוהי רשימה חלקית, אך מכסה את רוב המקרים הנפוצים.
        // יש להיזהר מכל תגית '!!' שאינה מוגדרת במפורש כבטוחה.
        Pattern dangerousTagsPattern = Pattern.compile(
            "!!(java|javax|org|com|net)\\..*" + // כל תגית שמתחילה ב-java.*, javax.* וכו'.
            "|!!(map|seq|str|int|float|bool|null)" + // תגיות בסיסיות בטוחות
            "|!!set" + // סט בטוח
            "|!!binary" + // בינארי בטוח
            "|!!timestamp", // חותמת זמן בטוחה
            Pattern.CASE_INSENSITIVE
        );

        // בדוק אם מחרוזת ה-YAML מכילה תגיות מסוכנות
        if (dangerousTagsPattern.matcher(yamlString).find()) {
            // אם נמצאה תגית מסוכנת, זרוק חריגה
            throw new YAMLException("Dangerous tag found in YAML string. Object instantiation is not allowed.");
        }

        // השתמש ב-Constructor כדי לקבוע במפורש את הסוגים המותרים, אם רלוונטי.
        // עבור מקרים פשוטים, Constructor ברירת המחדל עם סוג היעד מספיק.
        // אם נדרשת הגבלה הדוקה יותר, ניתן override את createClassFor.
        Constructor constructor = new Constructor(type);

        // Representer ברירת מחדל, לא משפיע על טעינה
        Representer representer = new Representer();

        // יצירת מופע של Yaml עם Constructor מותאם אישית
        Yaml yaml = new Yaml(constructor, representer);

        try {
            // טעינת האובייקט מה-YAML
            return yaml.load(yamlString);
        } catch (YAMLException e) {
            // עטוף או העבר הלאה חריגות של SnakeYAML
            throw new YAMLException("Failed to load YAML configuration: " + e.getMessage(), e);
        }
    }
}
