import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.inspector.TagInspector;

public class ClassX {
    /**
     * Charge la configuration à partir d'une chaîne YAML.
     *
     * La fonction vérifie les balises dangereuses explicites pour empêcher l'instanciation d'objets.
     *
     * @param yamlString La chaîne YAML à parser.
     * @param type La classe de l'objet de configuration attendu.
     * @param <T> Le type de l'objet de configuration.
     * @return L'objet de configuration parsé.
     * @throws org.yaml.snakeyaml.error.YAMLException Si la chaîne YAML est invalide ou contient une balise dangereuse.
     */
    public <T> T loadConfigFromString(String yamlString, Class<T> type) {
        // Créer un constructeur spécifique au type cible.
        // Cela permet à SnakeYAML de mapper les données YAML à la classe spécifiée.
        Constructor constructor = new Constructor(type);

        // Définir l'inspecteur de balises par défaut pour empêcher l'instanciation d'objets dangereux.
        // C'est une mesure de sécurité cruciale pour prévenir les vulnérabilités de désérialisation YAML,
        // telles que l'exécution de code à distance via des balises !!java.object.
        constructor.setTagInspector(TagInspector.DEFAULT);

        // Créer l'instance Yaml avec le constructeur configuré.
        Yaml yaml = new Yaml(constructor);

        // Charger (parser) la chaîne YAML dans un objet du type spécifié.
        return yaml.load(yamlString);
    }
}

