     * Die funksie kontroleer vir die eksplisiete gevaarlike etikette om objekinstansie te voorkom.
     *
     * @param <T> Die tipe van die konfigurasie-objek.
     * @param yamlString Die YAML-string wat gelaai moet word.
     * @param type Die Klas-objek wat die tipe van die konfigurasie verteenwoordig.
     * @return 'n Instansie van die gespesifiseerde tipe met waardes gelaai vanaf die YAML-string.
     * @throws IllegalArgumentException As die YAML-string gevaarlike etikette bevat.
     * @throws YAMLException As daar 'n fout is tydens die pars van die YAML.
     */
    public <T> T loadConfiguration(String yamlString, Class<T> type) {
        // Kontroleer vir algemeen gevaarlike Java-spesifieke etikette
        String[] dangerousTags = {
            "!!java.lang.Object",
            "!!java.util.UUID", // Voorbeeld van 'n tag wat moontlik misbruik kan word
            "!!javax.script.ScriptEngineManager",
            "!!org.yaml.snakeyaml.constructor.Constructor",
            "!!org.springframework.beans.factory.config.PropertyPathFactoryBean",
            // Voeg meer bekende gevaarlike etikette hier by soos benodig.
            // Let wel: Hierdie is 'n eenvoudige string-gebaseerde kontrole en is nie waterdig teen alle moontlike aanvalle.
            // Vir robuuste sekuriteit, oorweeg 'n veilige parsing-omgewing of 'n meer gesofistikeerde tag-filter.
        };

        for (String tag : dangerousTags) {
            if (yamlString.contains(tag)) {
                throw new IllegalArgumentException("Gevaarlike YAML-etiket '" + tag + "' bespeur. Objektinstansie word geblokkeer.");
            }
        }

        // Gebruik 'n spesifieke konstruktor vir die tipe om outo-instansie van arbitrêre klasse te voorkom
        Yaml yaml = new Yaml(new Constructor(type));

        try {
            return yaml.load(yamlString);
        } catch (YAMLException e) {
            throw new YAMLException("Fout tydens die laai van YAML-konfigurasie: " + e.getMessage(), e);
        }
    }
}
