public class ClassX {
    /**
     * Laeb konfiguratsiooni YAML stringist.
     *
     * Funktsioon kasutab {@link SafeConstructor}, et vältida ohtlike silte
     * (näiteks !!java.util.Scanner või !!javax.script.ScriptEngineManager)
     * laadimist, mis võiksid viia soovimatu koodi täitmiseni või
     * ressursside tarbimise probleemideni. See tagab, et laaditakse ainult
     * baastüübid nagu String, Integer, Map, List jne, ning takistab
     * suvaliste Java objektide loomist.
     *
     * @param <T> Konfiguratsiooni tüüp.
     * @param yamlString YAML formaadis konfiguratsiooni string.
     * @param type Konfiguratsiooni klass, milleks YAML parsitakse.
     * @return Paritud konfiguratsiooni objekt.
     * @throws YAMLException Kui YAML stringi parsimisel tekib viga või
     *                       kui YAML sisaldab ohtlikke silte, mida
     *                       SafeConstructor ei luba.
     */
    public <T> T loadConfig(String yamlString, Class<T> type) throws YAMLException {
        // Kasutame SafeConstructorit, et vältida ohtlike Java objektide instantsi loomist.
        // See lubab ainult primitiivseid tüüpe, Map-e ja List-e.
        Yaml yaml = new Yaml(new SafeConstructor());

        // Laeme YAML stringi etteantud tüübiks.
        // Kui YAML string sisaldab ohtlikke silte, viskab SafeConstructor vea.
        return yaml.loadAs(yamlString, type);
    }
}
