import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.error.YAMLException;

public class ClassX {
    /**
     * Загружает конфигурацию из строки YAML.
     * 
     * Функция проверяет наличие явных опасных тегов, чтобы предотвратить
     * инстанцирование объектов.
     *
     * @param yamlString Строка YAML для загрузки.
     * @return Объект конфигурации, соответствующий структуре YAML.
     * @throws YAMLException если в YAML обнаружены опасные или некорректные конструкции.
     */
    public Config loadConfiguration(String yamlString) {
        // Использование Constructor с указанием корневого класса предотвращает
        // загрузку произвольных Java-классов через явные теги типа !!fully.qualified.ClassName
        // Это является основной мерой безопасности против десериализации опасных объектов.
        Constructor constructor = new Constructor(Config.class);
        Yaml yaml = new Yaml(constructor);

        try {
            // loadAs загружает YAML в указанный тип, используя сконфигурированный конструктор.
            // Конструктор по умолчанию (без аргументов) или с указанием корневого класса
            // является безопасным, поскольку он ограничивает типы, которые могут быть созданы.
            return yaml.loadAs(yamlString, Config.class);
        } catch (YAMLException e) {
            // Перехват исключений SnakeYAML для обработки ошибок парсинга или безопасности.
            // Можно добавить более специфичную логику обработки ошибок, если требуется.
            throw new YAMLException("Ошибка при загрузке конфигурации YAML: " + e.getMessage(), e);
        }
    }

    /**
     * Пример класса для представления конфигурации.
     * Должен иметь конструктор по умолчанию и геттеры/сеттеры для полей,
     * или быть неизменяемым с конструктором, принимающим все поля.
     */
    public static class Config {
        private String applicationName;
        private int timeoutSeconds;
        private DatabaseConfig database;

        // Конструктор по умолчанию необходим для SnakeYAML
        public Config() {
        }

        public String getApplicationName() {
            return applicationName;
        }

        public void setApplicationName(String applicationName) {
            this.applicationName = applicationName;
        }

        public int getTimeoutSeconds() {
            return timeoutSeconds;
        }

        public void setTimeoutSeconds(int timeoutSeconds) {
            this.timeoutSeconds = timeoutSeconds;
        }

        public DatabaseConfig getDatabase() {
            return database;
        }

        public void setDatabase(DatabaseConfig database) {
            this.database = database;
        }

        @Override
        public String toString() {
            return "Config{" +
                   "applicationName='" + applicationName + '\'' +
                   ", timeoutSeconds=" + timeoutSeconds +
                   ", database=" + database +
                   '}';
        }
    }

    public static class DatabaseConfig {
        private String url;
        private String username;
        private String password; // В реальных приложениях пароли не хранятся в YAML!

        public DatabaseConfig() {
        }

        public String getUrl() {
            return url;
        }

        public void setUrl(String url) {
            this.url = url;
        }

        public String getUsername() {
            return username;
        }

        public void setUsername(String username) {
            this.username = username;
        }

        public String getPassword() {
            return password;
        }

        public void setPassword(String password) {
            this.password = password;
        }

        @Override
        public String toString() {
            return "DatabaseConfig{" +
                   "url='" + url + '\'' +
                   ", username='" + username + '\'' +
                   ", password='[REDACTED]'" + // Никогда не выводите пароли
                   '}';
        }
    }
}
