import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class ClassX {

    private static final Set<String> BLACKLISTED_DOMAINS;

    static {
        Set<String> domains = new HashSet<>();
        domains.add("malicious.com");
        domains.add("phishing.net");
        // Add more blacklisted domains as needed
        BLACKLISTED_DOMAINS = Collections.unmodifiableSet(domains);
    }

    /**
     * Redirects the user to a target URL.
     *
     * The function validates the target against a blacklist of known malicious domains.
     *
     * @param response The HttpServletResponse object.
     * @param targetUrl The URL to redirect to.
     * @throws IOException If an input or output error occurs.
     */
    public void redirectUser(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            // Log warning or throw exception for empty/null URL
            System.err.println("Attempted redirect to a null or empty URL.");
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Target URL cannot be empty.");
            return;
        }

        try {
            URL url = new URL(targetUrl);
            String host = url.getHost();

            if (host != null) {
                for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
                    // Check for exact match or subdomain match
                    if (host.equalsIgnoreCase(blacklistedDomain) || host.endsWith("." + blacklistedDomain)) {
                        // Log the attempted redirect to a blacklisted domain
                        System.err.println("Attempted redirect to a blacklisted domain: " + targetUrl);
                        // Instead of redirecting, you might:
                        // 1. Redirect to a safe default page.
                        // 2. Display an error page.
                        // 3. Throw a security exception.
                        response.sendError(HttpServletResponse.SC_FORBIDDEN, "Redirect target is forbidden.");
                        return;
                    }
                }
            }
        } catch (MalformedURLException e) {
            // Log invalid URL format
            System.err.println("Invalid URL format for redirect: " + targetUrl + " - " + e.getMessage());
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid target URL format.");
            return;
        }

        // If validation passes, perform the redirect
        response.sendRedirect(targetUrl);
    }
}
