     * @throws IOException Если произошла ошибка ввода-вывода при попытке перенаправления.
     * @throws SecurityException Если домен целевого URL находится в черном списке.
     * @throws IllegalArgumentException Если {@code targetUrl} является null, пустым или имеет некорректный формат.
     */
    public void redirectToUrl(HttpServletResponse response, String targetUrl)
            throws IOException, SecurityException, IllegalArgumentException {

        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("Целевой URL не может быть null или пустым.");
        }

        URL url;
        try {
            url = new URL(targetUrl);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Некорректный формат целевого URL: " + targetUrl, e);
