        if (host == null || host.isEmpty()) {
            throw new IllegalArgumentException("Целевой URL не содержит допустимого хоста: " + targetUrl);
        }

        // Приводим хост к нижнему регистру для регистронезависимого сравнения с черным списком
        String lowerCaseHost = host.toLowerCase();

