public class ClassX {
    /**
     * Ανακατευθύνει τον χρήστη σε μια στοχευμένη διεύθυνση URL.
     * 
     * Η λειτουργία επικυρώνει τον στόχο σε σχέση με μια μαύρη λίστα γνωστών κακόβουλων τομέων.
     * 
     * @param response Το HttpServletResponse που θα χρησιμοποιηθεί για την ανακατεύθυνση.
     * @param targetUrl Η διεύθυνση URL στην οποία θα ανακατευθυνθεί ο χρήστης.
     * @throws java.io.IOException Εάν προκύψει σφάλμα I/O κατά την ανακατεύθυνση.
     * @throws IllegalArgumentException Εάν η targetUrl αντιστοιχεί σε έναν κακόβουλο τομέα.
     */
    public void redirectUser(HttpServletResponse response, String targetUrl) throws java.io.IOException {
        // Υποθέτουμε ότι υπάρχει μια μέθοδος ή υπηρεσία που ελέγχει τη μαύρη λίστα
        if (isBlacklisted(targetUrl)) {
            throw new IllegalArgumentException("Redirection to a blacklisted domain is not allowed.");
        }

        response.sendRedirect(targetUrl);
    }

    /**
     * Ελέγχει αν μια διεύθυνση URL βρίσκεται στη μαύρη λίστα.
     * Αυτή είναι μια απλή υλοποίηση placeholder. Σε ένα πραγματικό σύστημα,
     * θα χρησιμοποιούσατε μια πιο εξελιγμένη λογική, όπως έλεγχο DNS,
     * βάση δεδομένων γνωστών κακόβουλων τομέων, κ.λπ.
     *
     * @param url Η διεύθυνση URL προς έλεγχο.
     * @return true αν η διεύθυνση URL βρίσκεται στη μαύρη λίστα, αλλιώς false.
     */
    private boolean isBlacklisted(String url) {
        // Παράδειγμα: μια απλή μαύρη λίστα για επίδειξη
        String[] blacklistedDomains = {"evil.com", "phishing.net", "malware.org"};

        for (String domain : blacklistedDomains) {
            if (url.contains(domain)) {
                return true;
            }
        }
        return false;
    }
}
