import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class ClassX {

    private static final Set<String> BLACKLISTED_DOMAINS;

    static {
        Set<String> domains = new HashSet<>();
        // Add known malicious or phishing domains to the blacklist
        domains.add("malicious-phishing-site.com");
        domains.add("bad-domain.net");
        domains.add("evil-scam.org");
        // Add more domains as needed
        BLACKLISTED_DOMAINS = Collections.unmodifiableSet(domains);
    }

    /**
     * I-redirect ang gumagamit sa isang target na URL.
     *
     * Ang function ay nagva-validate ng target laban sa isang blacklist ng mga kilalang mapanlinlang na domain.
     *
     * @param response Ang HttpServletResponse object para sa paggawa ng redirect.
     * @param targetUrl Ang URL na irere-direct sa.
     * @throws IllegalArgumentException Kung ang targetUrl ay null, walang laman, malformed, o nasa blacklist.
     * @throws IOException Kung may error sa I/O habang nagre-redirect.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("Target URL cannot be null or empty.");
        }

        URL url;
        try {
            url = new URL(targetUrl);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid target URL format: " + targetUrl, e);
        }

        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Target URL does not contain a valid host: " + targetUrl);
        }

        // Normalize host to lowercase for case-insensitive comparison
        String normalizedHost = host.toLowerCase();

        if (BLACKLISTED_DOMAINS.contains(normalizedHost)) {
            // Log this attempt for security monitoring
            System.err.println("Attempted redirect to blacklisted domain: " + normalizedHost + " from URL: " + targetUrl);
            throw new IllegalArgumentException("Redirect to blacklisted domain is not allowed: " + normalizedHost);
        }

        // Perform the redirect
        response.sendRedirect(targetUrl);
    }
}
