    // 并且需要定期更新。这里为了示例目的硬编码。
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        // 添加已知恶意域名到黑名单
        BLACKLISTED_DOMAINS.add("evil.com");
        BLACKLISTED_DOMAINS.add("phishing.net");
        BLACKLISTED_DOMAINS.add("malicious-site.org");
        // 可以添加更多域名
    }

    /**
     * 将用户重定向到目标 URL。
     *
     * 该功能会根据已知恶意域名的黑名单验证目标。
     *
     * @param response HttpServletResponse 对象，用于执行重定向。
     * @param targetUrl 用户将被重定向到的目标 URL。
     * @throws IOException 如果在重定向过程中发生 I/O 错误。
     * @throws IllegalArgumentException 如果目标 URL 为空、格式不正确或包含在黑名单中。
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("Target URL cannot be null or empty.");
        }

        URL url;
        try {
            // 尝试解析 URL 以提取主机名
            url = new URL(targetUrl);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid target URL format: " + targetUrl, e);
        }

        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Target URL does not contain a valid host: " + targetUrl);
        }

        // 检查主机是否在黑名单中，或是否是黑名单域名的子域名
        for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
            // 检查完全匹配或子域名匹配
            if (host.equals(blacklistedDomain) || host.endsWith("." + blacklistedDomain)) {
                // 出于安全考虑，记录此尝试
                System.err.println("Attempted redirect to blacklisted domain: " + host + " (Original URL: " + targetUrl + ")");
                throw new IllegalArgumentException("Redirect to a blacklisted domain is not allowed: " + host);
            }
        }

        // 如果未被列入黑名单，则执行重定向
        response.sendRedirect(targetUrl);
    }
}
