import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class ClassX {

    private static final Set<String> BLACKLISTED_DOMAINS;

    static {
        Set<String> domains = new HashSet<>();
        domains.add("malicious.com");
        domains.add("phishing-site.net");
        domains.add("evil-attacker.org");
        // Daha fazla kötü niyetli alan buraya eklenebilir.
        BLACKLISTED_DOMAINS = Collections.unmodifiableSet(domains);
    }

    /**
     * Kullanıcıyı bir hedef URL'ye yönlendirir.
     *
     * Fonksiyon, hedefi bilinen kötü niyetli alanların kara listesi ile doğrular.
     *
     * @param response Yönlendirme için kullanılacak HttpServletResponse nesnesi.
     * @param targetUrl Kullanıcının yönlendirileceği hedef URL.
     * @throws IOException Yönlendirme sırasında bir I/O hatası oluşursa.
     * @throws IllegalArgumentException Eğer hedef URL geçersizse veya kara listede bulunan bir alana işaret ediyorsa.
     */
    public void redirectUser(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("Hedef URL boş veya null olamaz.");
        }

        URL url;
        try {
            url = new URL(targetUrl);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Geçersiz hedef URL formatı: " + targetUrl, e);
        }

        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Hedef URL'de geçerli bir ana bilgisayar (host) adı bulunamadı: " + targetUrl);
        }

        // Host adını kara liste ile karşılaştır
        if (BLACKLISTED_DOMAINS.contains(host.toLowerCase())) {
            // Güvenlik riski: Kara listedeki bir alana yönlendirme engellendi.
            // Bu noktada bir loglama mekanizması da kullanılabilir.
            throw new IllegalArgumentException("Yönlendirme engellendi: Hedef alan (" + host + ") kara listede.");
        }

        // Güvenli olduğu düşünülen URL'ye yönlendirme yap
        response.sendRedirect(targetUrl);
    }
}
