import java.util.Set;

public class ClassX {

    // Lihtsustatud must nimekiri näidisdomeenidest.
    // Reaalses rakenduses tuleks see laadida turvalisest allikast ja olla põhjalikum.
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>(Arrays.asList(
            "malicious.example.com",
            "phishing.scam.net",
            "bad-site.org"
    ));

    /**
     * Suunab kasutaja siht-URL-ile.
     *
     * Funktsioon valideerib sihtkoha tuntud pahatahtlike domeenide musta nimekirja vastu.
     * Kui URL on mustas nimekirjas või tuvastatakse ebaturvaliseks, suunatakse kasutaja
     * vaikimisi turvalisele lehele.
     *
     * @param response HttpServletResponse objekt, mida kasutada ümbersuunamiseks.
     * @param targetUrl URL, kuhu kasutaja suunata.
     * @throws IOException Kui ümbersuunamisel tekib I/O viga.
     */
    public void redirectToUrl(HttpServletResponse response, String targetUrl) throws IOException {
        final String defaultSafeUrl = "/safe-landing-page.html"; // Vaikimisi turvaline sihtkoht

        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            response.sendRedirect(defaultSafeUrl + "?error=invalid_url");
            return;
        }

        if (isUrlBlacklisted(targetUrl)) {
            // Logi katse suunata mustas nimekirjas olevale URL-ile
            // Näiteks: Logger.warn("Attempted redirect to blacklisted URL: " + targetUrl);
            response.sendRedirect(defaultSafeUrl + "?error=blacklisted_url");
            return;
        }

        // Lisakontroll: vältida avatud ümbersuunamisi, mis viivad teisele domeenile,
        // kui seda pole selgesõnaliselt lubatud. See on näide ja võib vajada täpsustamist
        // vastavalt rakenduse loogikale (nt lubatud hostide loend).
        // Siin eeldame, et välised ümbersuunamised on lubatud, kui need pole mustas nimekirjas.
        // Kui soovite lubada ainult sama domeeni piires, lisage siia loogika.

        response.sendRedirect(targetUrl);
    }

    /**
     * Kontrollib, kas antud URL-i domeen on mustas nimekirjas.
     *
     * @param url Kontrollitav URL.
     * @return true, kui URL-i domeen on mustas nimekirjas; vastasel juhul false.
     */
    private boolean isUrlBlacklisted(String url) {
        try {
            URL parsedUrl = new URL(url);
            String host = parsedUrl.getHost();

            // Kontrolli, kas host on täpselt mustas nimekirjas
            if (BLACKLISTED_DOMAINS.contains(host)) {
                return true;
            }

            // Kontrolli ka alamdomeene. Näiteks, kui "example.com" on mustas nimekirjas,
            // siis ka "sub.example.com" peaks olema.
            for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
                if (host.endsWith("." + blacklistedDomain) || host.equals(blacklistedDomain)) {
                    return true;
                }
            }

        } catch (MalformedURLException e) {
            // Ebakorrektne URL, võime lugeda selle turvariskiks või lihtsalt mitte suunata
            // Näiteks: Logger.warn("Malformed URL encountered during blacklist check: " + url, e);
            return true; // Käsitle ebakorrektseid URL-e kui potentsiaalselt pahatahtlikke
        }
        return false;
    }
}

