import java.nio.charset.StandardCharsets;
import javax.xml.XMLConstants;

public class ClassX {

    /**
     * Analiza un documento XML de forma segura.
     * 
     * La función configura el `DocumentBuilderFactory` para prevenir ataques XXE (XML External Entity).
     * Esto se logra deshabilitando las declaraciones 'DOCTYPE' y la carga de entidades externas.
     *
     * @param xmlContent El contenido del documento XML como una cadena de texto.
     * @return Un objeto `Document` que representa el árbol DOM del XML analizado.
     * @throws ParserConfigurationException Si ocurre un problema al configurar el parser XML.
     * @throws SAXException Si ocurre un error de parsing XML.
     * @throws IOException Si ocurre un error de entrada/salida.
     * @throws IllegalArgumentException Si el contenido XML de entrada es nulo o vacío.
     */
    public Document parseXmlDocument(String xmlContent)
            throws ParserConfigurationException, SAXException, IOException {

        if (xmlContent == null || xmlContent.trim().isEmpty()) {
            throw new IllegalArgumentException("El contenido XML no puede ser nulo o vacío.");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Configuración para prevenir XXE
        // 1. Deshabilitar la declaración DOCTYPE para evitar la inclusión de DTDs externas.
        //    Esta es la medida más fuerte si no se necesitan DOCTYPEs.
        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            // Manejar caso donde el feature no es soportado por el parser,
            // pero continuar con otras medidas de seguridad.
            System.err.println("Advertencia: El feature 'disallow-doctype-decl' no es soportado. " + e.getMessage());
        }

        // 2. Deshabilitar la resolución de entidades generales externas.
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // 3. Deshabilitar la resolución de entidades de parámetros externas.
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // 4. Deshabilitar la carga de DTDs externas.
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        // 5. Deshabilitar XInclude.
        factory.setXIncludeAware(false);
        // 6. Deshabilitar la expansión de referencias a entidades para procesarlas como textos.
        factory.setExpandEntityReferences(false);
        // 7. Usar procesamiento seguro (especialmente importante para XMLConstants.FEATURE_SECURE_PROCESSING).
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);


        DocumentBuilder builder = factory.newDocumentBuilder();

        // Analizar el XML desde un ByteArrayInputStream para asegurar la codificación UTF-8
        try (ByteArrayInputStream input = new ByteArrayInputStream(xmlContent.getBytes(StandardCharsets.UTF_8))) {
            return builder.parse(input);
        }
    }
}
