import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets; // Use StandardCharsets for consistent byte conversion

public class ClassX {

    /**
     * Analiza un documento XML de forma segura, previniendo ataques de Entidades Externas XML (XXE).
     *
     * La función configura el `DocumentBuilderFactory` para deshabilitar el procesamiento de
     * declaraciones 'DOCTYPE' y la resolución de entidades externas, mitigando así las vulnerabilidades XXE.
     *
     * @param xmlContent La cadena que contiene el contenido XML a analizar.
     * @return Un objeto {@link Document} que representa el XML analizado, o {@code null} si ocurre un error
     *         durante el análisis o la configuración del parser.
     */
    public Document parseXmlSecurely(String xmlContent) {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        try {
            // --- Medidas de Prevención XXE ---

            // 1. Deshabilitar la declaración de DOCTYPE completamente.
            //    Esto previene la inclusión de DTD externas y, por lo tanto, la mayoría de los ataques XXE.
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // 2. Deshabilitar la resolución de entidades generales externas.
            //    Asegura que las entidades definidas en el XML no puedan referenciar recursos externos.
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

            // 3. Deshabilitar la resolución de entidades de parámetros externas.
            //    Similar a la anterior, pero para entidades de parámetros en DTDs.
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            // 4. Deshabilitar XInclude.
            //    Previene la inclusión de documentos XML externos usando la sintaxis XInclude.
            factory.setXIncludeAware(false);

            // 5. Deshabilitar la expansión de referencias a entidades.
            //    Puede prevenir algunos ataques DoS a través de 'billion laughs' si las entidades no se manejan bien.
            factory.setExpandEntityReferences(false);

            // 6. Configuración adicional de seguridad para algunos parsers (opcional pero buena práctica)
            //    Por ejemplo, para parsers que aún pueden procesar DOCTYPEs a pesar de las flags anteriores
            //    (aunque "disallow-doctype-decl" debería ser suficiente).
            //    Para Oracle/Sun/OpenJDK JAXP:
            //    factory.setFeature("http://javax.xml.XMLConstants/feature/secure-processing", true);
            //    factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);


            DocumentBuilder builder = factory.newDocumentBuilder();
            return builder.parse(new ByteArrayInputStream(xmlContent.getBytes(StandardCharsets.UTF_8)));

        } catch (ParserConfigurationException e) {
            // Error en la configuración del parser (ej. feature no soportada)
            System.err.println("Error de configuración del parser: " + e.getMessage());
        } catch (SAXException e) {
            // Error durante el análisis del XML (XML mal formado, etc.)
            System.err.println("Error SAX al analizar el XML: " + e.getMessage());
        } catch (IOException e) {
            // Error de I/O (no esperado con ByteArrayInputStream, pero posible)
            System.err.println("Error de I/O al analizar el XML: " + e.getMessage());
        }
        return null;
    }
}
