    public Document parseXmlDocument(byte[] xmlBytes) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // XXE-Prävention:
        // 1. Deaktiviert die Verarbeitung von DOCTYPE-Deklarationen, die eine Hauptquelle für XXE sind.
        //    Dies verhindert das Laden von externen DTDs und die Auflösung von externen Entitäten.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // 2. Allgemeine sichere Verarbeitung
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // 3. Deaktiviert externe allgemeine Entitäten (wenn disallow-doctype-decl nicht ausreicht oder explizit sein soll)
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // 4. Deaktiviert externe Parameterentitäten
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // 5. Verhindert das Laden von externen DTDs (redundant, wenn disallow-doctype-decl true ist, aber gute Praxis)
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        // 6. Deaktiviert XInclude (falls nicht benötigt, kann auch eine Quelle für externe Ressourcen sein)
        factory.setXIncludeAware(false);

