     */
    public Document parseXmlDocument(String xmlContent)
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Konfigurasi pabrik untuk mencegah serangan XXE (XML External Entity).
        // Fitur ini secara eksplisit melarang pemrosesan deklarasi DOCTYPE.
        // Jika deklarasi DOCTYPE ditemukan, parser akan melemparkan SAXException.
        // Ini adalah cara utama untuk mencegah XXE yang memanfaatkan DTD.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

