import java.io.IOException;
import java.net.URL;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Fetches content from a URL.
     * 
     * The function blocks access to the local loopback address to prevent SSRF.
     * @param urlString The URL to fetch content from.
     * @return The content fetched from the URL as a String.
     * @throws IOException If an I/O error occurs during fetching or if the URL is malformed.
     * @throws IllegalArgumentException If the URL points to a local loopback address,
     *                                  which is blocked for security reasons.
     */
    public String fetchContentFromURL(String urlString) throws IOException {
        URL url = new URL(urlString);
        String host = url.getHost();

        // Prevent Server-Side Request Forgery (SSRF) by blocking access to loopback addresses
        try {
            // Resolve the host to its IP address(es)
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress address : addresses) {
                if (address.isLoopbackAddress()) {
                    throw new IllegalArgumentException(
                        "Access to loopback address '" + host + "' (" + address.getHostAddress() + ") is blocked to prevent SSRF."
                    );
                }
                // Optionally, add checks for private IP ranges (e.g., isSiteLocalAddress())
                // if the threat model requires blocking internal network access as well.
                // For this problem, only loopback is explicitly required.
            }
        } catch (UnknownHostException e) {
            // If the host cannot be resolved, it's not a loopback address.
            // The connection attempt will likely fail later if it's truly unresolvable.
            // For security, an unresolvable host is generally safer than a resolvable forbidden one.
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
