public class ClassX {
    /**
     * Obtiene contenido de una URL.
     * 
     * La función bloquea el acceso a la dirección de bucle invertido local para prevenir SSRF.
     * 
     * @param urlString La URL de la cual obtener el contenido.
     * @return El contenido de la URL como una cadena de texto.
     * @throws IOException Si ocurre un error de E/S o si la URL apunta a una dirección de bucle invertido.
     */
    public String getURLContent(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("La URL proporcionada no es válida: " + urlString + ". " + e.getMessage());
        }

        // Prevenir SSRF: Verificar si el host resuelve a una dirección de bucle invertido
        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IOException("La URL no especifica un host válido: " + urlString);
        }

        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress addr : addresses) {
                if (addr.isLoopbackAddress() || addr.isSiteLocalAddress()) { // isSiteLocalAddress for private networks
                    throw new IOException("Acceso denegado: Se ha detectado un intento de conexión a una dirección de bucle invertido o red local (" + addr.getHostAddress() + "). Posible intento de SSRF.");
                }
            }
        } catch (UnknownHostException e) {
            // Si el host no puede resolverse, podría ser un host no existente o un intento malicioso.
            // Para mayor seguridad, podríamos optar por bloquearlo o registrar la anomalía.
            // Aquí, permitimos que la conexión falle de forma natural si el host no existe.
            // O podríamos lanzar una excepción explícita si se considera un riesgo.
            // throw new IOException("No se pudo resolver el host: " + host + ". " + e.getMessage());
        }

        StringBuilder content = new StringBuilder();
        BufferedReader reader = null;
        try {
            URLConnection connection = url.openConnection();
            // Opcional: Establecer un tiempo de espera para la conexión y lectura
            connection.setConnectTimeout(5000); // 5 segundos
            connection.setReadTimeout(10000);   // 10 segundos

            reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Ignorar errores al cerrar el lector
                }
            }
        }
        return content.toString();
    }
}
