import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * שולף תוכן מ-URL.
     * <p>
     * הפונקציה חוסמת גישה לכתובת הלולאה המקומית כדי למנוע SSRF.
     *
     * @param urlString ה-URL שממנו יש לשלוף תוכן.
     * @return תוכן ה-URL כמחרוזת.
     * @throws IllegalArgumentException אם ה-URL מפנה לכתובת לולאה מקומית (SSRF).
     * @throws MalformedURLException    אם ה-URL אינו בפורמט חוקי.
     * @throws IOException              אם מתרחשת שגיאת קלט/פלט במהלך גישה ל-URL.
     */
    public static String fetchUrlContent(String urlString) throws MalformedURLException, IOException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("URL string cannot be null or empty.");
        }

        URL url = new URL(urlString);

        // SSRF protection: Check if the host resolves to a loopback address
        String host = url.getHost();
        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress address : addresses) {
                if (address.isLoopbackAddress()) {
                    throw new IllegalArgumentException("Access to loopback address (SSRF attempt) is blocked: " + host);
                }
            }
        } catch (UnknownHostException e) {
            // If the host cannot be resolved, it's likely a malformed URL or network issue,
            // which will be caught by subsequent URL connection attempts.
            // For SSRF, we primarily care about *resolvable* loopback addresses.
            // Re-throwing as IOException to indicate a general network issue.
            throw new IOException("Could not resolve host: " + host, e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
        }
        return content.toString();
    }
}
