import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Ruft Inhalte von einer URL ab.
     *
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF zu verhindern.
     * @param urlString Die URL, von der Inhalte abgerufen werden sollen.
     * @return Der Inhalt der URL als String.
     * @throws IOException wenn ein E/A-Fehler auftritt oder die URL ungültig ist.
     * @throws SecurityException wenn versucht wird, auf eine Loopback-Adresse zuzugreifen (SSRF-Schutz).
     */
    public String getContentFromUrl(String urlString) throws IOException, SecurityException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new IOException("Ungültiges URL-Format: " + urlString, e);
        }

        String host = url.getHost();
        if (host == null || host.isEmpty()) {
            throw new IOException("Die URL enthält keinen Host oder ist nicht für HTTP/HTTPS geeignet: " + urlString);
        }

        InetAddress[] addresses;
        try {
            // Resolve all IP addresses for the given host
            addresses = InetAddress.getAllByName(host);
        } catch (UnknownHostException e) {
            throw new IOException("Host unbekannt: " + host, e);
        }

        // Check if any resolved address is a loopback address
        for (InetAddress address : addresses) {
            if (address.isLoopbackAddress()) {
                throw new SecurityException("Zugriff auf Loopback-Adresse verweigert (SSRF-Schutz): " + host + " (" + address.getHostAddress() + ")");
            }
            // Additional checks could be added here for private IP ranges (RFC1918)
            // if more comprehensive SSRF protection is desired.
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}

